function loadSampleJSON(input, options = {}) {
  const loadGeneration = ++libraryLoadGeneration;
  if (typeof input === "string") {
    // Load necessary information from JSON
    return fetch(input)
      .then((response) => response.json())
      .then((data) => {
        if (loadGeneration !== libraryLoadGeneration) return false;
        return processJSON(data, options); // Process JSON data
      });
  } else if (typeof input === "object") {
    // Case 2: Input is already parsed JSON
    return processJSON(input, options);
  }

  return Promise.resolve();
}

function getLibraryStorageKey(data = currentLibraryData) {
  if (currentLibraryPath) return currentLibraryPath;
  const titles = Array.isArray(data?.samples)
    ? data.samples.map((sample) => sample?.title || "").join("|")
    : "";
  return titles || "default";
}

function getLastSamplePreference(data = currentLibraryData) {
  try {
    const preference = JSON.parse(
      localStorage.getItem(LAST_SAMPLE_STORAGE_KEY) || "null",
    );
    if (!preference || preference.libraryKey !== getLibraryStorageKey(data)) {
      return null;
    }
    return preference;
  } catch (error) {
    console.warn("Could not read last sample preference:", error);
    return null;
  }
}

function saveLastSamplePreference(sampleIndex) {
  const sample = samples?.[sampleIndex];
  if (!sample) return;
  try {
    localStorage.setItem(
      LAST_SAMPLE_STORAGE_KEY,
      JSON.stringify({
        libraryKey: getLibraryStorageKey(),
        sampleTitle: sample.title || "",
      }),
    );
  } catch (error) {
    console.warn("Could not save last sample preference:", error);
  }
}

async function processJSON(data, options = {}) {
  const { autoLoadSample = true } = options;
  const requestedGroup = getQueryParameter("group");
  const restrictToRequestedGroup = embedMode && Boolean(requestedGroup);
  currentIndex = 0;
  currentLibraryData = data;
  samples = data.samples;
  ensureInMemorySampleIds(samples);
  annotationFiles = {}; // For loading predefined annotations
  groupMapping = {}; // To map groups to sample indices
  lastSelectedSampleByGroup = {};
  committedGroupSelection = "";

  samples.forEach((sample, index) => {
    annotationFiles[sample.title] = sample.annotations;

    // Ensure each tile set with angles is sorted ascending by angle.
    for (let tileSet of sample.tileSets) {
      if (tileSet.periodDegrees) {
        tileSet.tiles.sort((a, b) => a.angleDegrees - b.angleDegrees);
      }
    }

    // Map sample indices to their groups.
    if (sample.groups) {
      sample.groups.forEach((group) => {
        if (!groupMapping[group]) {
          groupMapping[group] = [];
        }
        groupMapping[group].push(index);
      });
    }
  });

  if (restrictToRequestedGroup) {
    groupMapping = groupMapping[requestedGroup]
      ? { [requestedGroup]: groupMapping[requestedGroup] }
      : {};
  } else {
    // Standalone mode retains every library group and the combined "All" option.
    groupMapping["All"] = Array.from({ length: samples.length }, (_, i) => i);
  }

  populateGroupDropdown();
  disableCountButtons();
  updateStageRotationCheck();

  const sampleParam = getQueryParameter("sample");
  const groupParam = requestedGroup;
  const lastSamplePreference = autoLoadSample
    ? getLastSamplePreference(data)
    : null;
  const preferredSampleTitle =
    sampleParam || lastSamplePreference?.sampleTitle || "";
  if (preferredSampleTitle) {
    let sampleIndex = samples.findIndex((sample) =>
      [sample.id, sample.sampleId, sample.title].filter(Boolean).includes(preferredSampleTitle),
    );
    if (
      sampleIndex !== -1 &&
      !Object.values(groupMapping).some((indices) => indices.includes(sampleIndex))
    ) {
      sampleIndex = -1;
    }
    if (sampleIndex !== -1) {
      const groupForSample = groupMapping[groupParam]?.includes(sampleIndex)
        ? groupParam
        : Object.keys(groupMapping).find((group) => groupMapping[group].includes(sampleIndex));
      document.getElementById("groupDropdown").value = groupForSample || "All";
      rememberSelectedSampleForGroup(groupForSample || "All", sampleIndex);
      populateSampleDropdown(groupForSample || "All", { autoSelect: false });
      document.getElementById("sampleDropdown").value = sampleIndex;
      if (autoLoadSample) {
        document
          .getElementById("sampleDropdown")
          .dispatchEvent(new Event("change"));
      }
      return;
    }
    console.error(`The requested sample “${preferredSampleTitle}” is not in this library.`);
    const fallbackGroup = groupMapping[groupParam] ? groupParam : "All";
    document.getElementById("groupDropdown").value = fallbackGroup;
    populateSampleDropdown(fallbackGroup, { autoSelect: false });
    return;
  }

  const firstGroup = groupMapping[groupParam] ? groupParam : Object.keys(groupMapping)[0];
  if (firstGroup) {
    document.getElementById("groupDropdown").value = firstGroup;
    populateSampleDropdown(firstGroup, { autoSelect: autoLoadSample });
  }
}

// Automatically load the default JSON file when the page loads
document.addEventListener("DOMContentLoaded", async () => {
  initializeEmbedCommandApi();
  let libraryLoaded = false;
  if (window.electronAPI?.initializeProjectLibrary) {
    try {
      const result = await window.electronAPI.initializeProjectLibrary();
      currentLibraryPath = result?.filePath || "";
      await loadSampleJSON(result.jsonData);
      libraryLoaded = true;
    } catch (error) {
      console.error("Could not initialize project library:", error);
    }
  }

  if (!libraryLoaded) {
    await loadSampleJSON(getRequestedLibraryUrl());
  }
  initializeToolPaletteWorkspacePersistence();
});

async function loadLibraryWithElectronDialog() {
  await flushAnnotationAutosave();
  await flushCountAutosave();
  if (!confirmDiscardUnsavedWork("Loading another library")) return;
  try {
    const result = await window.electronAPI.selectExistingJsonFile({
      persistSampleIds: true,
    });
    if (result?.canceled) return;

    clearUnsavedWork();
    currentLibraryPath = result.filePath || "";
    await loadSampleJSON(result.jsonData);
  } catch (error) {
    console.error("Error loading library JSON:", error);
    alert(error.message || "Invalid library JSON file.");
  }

  const menu = document.getElementById("imageSettingsMenu");
  menu.style.display = "none";
}

async function changeProjectWithElectronDialog() {
  await flushAnnotationAutosave();
  await flushCountAutosave();
  if (!confirmDiscardUnsavedWork("Changing projects")) return;
  try {
    const result = await window.electronAPI.changeProjectLibrary();
    if (!result?.jsonData) return;

    clearUnsavedWork();
    currentLibraryPath = result.filePath || "";
    await loadSampleJSON(result.jsonData);
  } catch (error) {
    console.error("Error opening project:", error);
    alert(error.message || "Could not open the selected project.");
  }

  const menu = document.getElementById("imageSettingsMenu");
  menu.style.display = "none";
}

