function isRemoteImageUri(uri) {
  return (
    typeof uri === "string" &&
    /^https?:\/\//i.test(uri) &&
    !/^https?:\/\/(127\.0\.0\.1|localhost|\[?::1\]?)([:/]|$)/i.test(uri)
  );
}

function clearImageLoadFailure() {
  if (!imageLoadFailure) return;
  imageLoadFailure.hidden = true;
  imageLoadFailureKey = "";
}

function showImageLoadFailure({ uri = "", generation = tileLoadGeneration } = {}) {
  if (!imageLoadFailure || imageLoadSuccessfulGenerations.has(generation)) return;

  const failureKey = `${currentIndex}:${generation}`;
  if (failureKey === imageLoadFailureKey) return;
  imageLoadFailureKey = failureKey;

  const remote = isRemoteImageUri(uri);
  const sampleTitle = samples[currentIndex]?.title || "The selected sample";
  const explicitlyOffline = remote && navigator.onLine === false;

  imageLoadFailureTitle.textContent = remote
    ? "Online image unavailable"
    : "Image unavailable";
  imageLoadFailureMessage.textContent = remote
    ? explicitlyOffline
      ? `You appear to be offline. “${sampleTitle}” is stored online and cannot be loaded without an internet connection.`
      : `“${sampleTitle}” is stored online and could not be loaded. Check your connection and try again, or open a library containing local images.`
    : `The image files for “${sampleTitle}” could not be loaded. Check that the files are available, or open another library.`;
  openLibraryFromFailureButton.textContent = window.electronAPI?.changeProjectLibrary
    ? "Open Project…"
    : "Load Library…";
  imageLoadFailure.hidden = false;
}

function handleTileLoadFailed(event) {
  if (imageLoadSuccessfulGenerations.has(tileLoadGeneration)) return;
  showImageLoadFailure({
    uri: event?.tile?.getUrl?.() || tileSets()[0]?.tiles?.[0]?.uri || "",
  });
}

function handleImageLoadSucceeded() {
  imageLoadSuccessfulGenerations.add(tileLoadGeneration);
  clearImageLoadFailure();
  maybeOpenLaunchWelcome();
}

/// Event listener for sample selection change (only add once)
document
  .getElementById("sampleDropdown")
  .addEventListener("change", async function () {
    const requestedIndex = Number(this.value);
    const sampleChanged = requestedIndex !== currentIndex;
    if (sampleChanged) await flushAnnotationAutosave();
    if (sampleChanged) await flushCountAutosave();
    if (
      sampleChanged &&
      !confirmDiscardUnsavedWork("Changing samples")
    ) {
      restoreCommittedSampleSelection();
      return;
    }
    if (sampleChanged) clearUnsavedWork();

    try {
      const previousTileSets = [...tileSets()];
      if (porosityThicknessOverlayEnabled) {
        porosityThicknessOverlayEnabled.checked = false;
      }
      clearPorosityThicknessDisplay(
        "Estimate porosity to calculate local thickness",
      );
      currentIndex = requestedIndex;
      invalidateClassifyFeatures();
      invalidateClassifyImageModel({ status: false });
      resetMobileAnnotationState();
      committedGroupSelection =
        document.getElementById("groupDropdown")?.value || "All";
      rememberSelectedSampleForCurrentGroup(currentIndex);
      saveLastSamplePreference(currentIndex);
      hideSampleInfoPopover();
      closeScaleWizard();
      stopSnapshotDrawMode({ clearSelection: true });
      porositySelectedTileSetIndices = [];
      if (porosityTileSetSelect) porosityTileSetSelect.innerHTML = "";
      resetPorosityAnalysis({ resetTypes: true });
      restoreCurrentSampleTileAppearancePreference();
      renderPorosityTileSetSelect();
      buildImageCheckboxes();
      buildOpacitySliders();
      buildTileAppearanceControls();
      resetTransformImageryForSampleChange(previousTileSets);
      clearAnnotations({ markUnsaved: false });
      annotationHistory.reset();
      updateImageCheckboxLabels();
      clearGrid();
      enableGridButtons();
      disableCountButtons();
      removeAoiRectangle();
      resetOpacitySliders();
      resetLockStage();
      updateOpacityImageSliderVisibility();
      updateOpacitySliderLabels();
      updateTileAppearanceControls();
      if (measurementControlsInitialized) {
        resetMeasurements(true);
      }
      document.getElementById("enableDivideImages").checked = !mobileMode;
      enableDivideImages = !mobileMode;
      const canLoadTiles = await confirmSampleTilesAvailable();
      if (!canLoadTiles) {
        return;
      }
      await loadTileSet();
      resetRotation(
        window.PetroImageSampleOrientation.getInitialRotationDegrees(
          samples[currentIndex],
        ),
      );
      displayImages();
      toggleOnImages();
      updateStageRotationCheck();
      updateScaleDependentControls();
      addScalebar();
      await restoreWorkingAnnotationsForCurrentSample();
      await restoreWorkingCountsForCurrentSample();
      populateClassifyControls();
    } catch (error) {
      console.error("[sample-switch] failed", error);
      throw error;
    }

    const annoJSONButtonContainer = document.getElementById("loadAnnoFromJSON");
    annoJSONButtonContainer.innerHTML = "";

    // Check if the selected sample has annotations
    const annotationFileOptions = normalizeAnnotationFileOptions(
      annotationFiles[title()],
    );
    configureMobileAnnotationControl(annotationFileOptions);
    if (annotationFileOptions.length > 0 && !mobileMode) {
      hasAnnotationInJSON = true;
      const button = document.createElement("button");
      button.textContent = "Load Existing Annotations";
      button.id = "loadAnnoFromJSONButton";
      button.className = "custom-button";
      button.style.setProperty("--button-width", "170px"); // button.style.display = "block"; // Make sure the button is visible
      annoJSONButtonContainer.appendChild(button);

      if (annotationFileOptions.length === 1) {
        button.onclick = () =>
          loadAnnotationsFromJSON(annotationFileOptions[0]);
      } else {
        const dropdown = document.createElement("div");
        dropdown.id = "loadAnnoFromJSONDropdown";
        dropdown.className = "annotation-json-dropdown";
        dropdown.style.display = "none";

        annotationFileOptions.forEach((file, index) => {
          const optionButton = document.createElement("button");
          optionButton.type = "button";
          optionButton.textContent = getAnnotationFileLabel(
            file,
            index,
            annotationFileOptions.length,
          );
          optionButton.title = file;
          optionButton.addEventListener("click", () => {
            dropdown.style.display = "none";
            loadAnnotationsFromJSON(file);
          });
          dropdown.appendChild(optionButton);
        });

        button.onclick = (event) => {
          event.stopPropagation();
          dropdown.style.display =
            dropdown.style.display === "block" ? "none" : "block";
        };

        annoJSONButtonContainer.appendChild(dropdown);
      }
    } else {
      hasAnnotationInJSON = annotationFileOptions.length > 0;
    }

    const selectedSample = samples[currentIndex];
    postViewerEvent("viewer.sampleChanged", {
      sampleId: selectedSample?.id || selectedSample?.sampleId || "",
      title: selectedSample?.title || "",
      group: document.getElementById("groupDropdown")?.value || "All",
    });
  });

function normalizeAnnotationFileOptions(annotationEntry) {
  if (Array.isArray(annotationEntry)) {
    return annotationEntry.filter((file) => typeof file === "string" && file);
  }

  if (typeof annotationEntry === "string" && annotationEntry) {
    return [annotationEntry];
  }

  return [];
}

function getAnnotationFileLabel(file, index) {
  const pathWithoutQuery = file.split(/[?#]/)[0];
  const fileName = pathWithoutQuery.split(/[\\/]/).filter(Boolean).pop();

  if (!fileName) {
    return `Annotations ${index + 1}`;
  }

  return decodeURIComponent(fileName).replace(/\.(geo)?json$/i, "");
}

function resetMobileAnnotationState() {
  mobileAnnotationState = {
    files: [],
    loaded: false,
    visible: false,
    busy: false,
    file: "",
  };
  const control = document.getElementById("mobileAnnotationControl");
  const dropdown = document.getElementById("mobileAnnotationDropdown");
  if (control) control.hidden = true;
  if (dropdown) {
    dropdown.hidden = true;
    dropdown.innerHTML = "";
  }
  if (mobileMode) {
    const groupDropdown = document.getElementById("groupDropdown");
    const sampleDropdown = document.getElementById("sampleDropdown");
    if (groupDropdown) groupDropdown.disabled = false;
    if (sampleDropdown) sampleDropdown.disabled = false;
  }
}

function updateMobileAnnotationControl() {
  if (!mobileMode) return;
  const control = document.getElementById("mobileAnnotationControl");
  const button = document.getElementById("mobileAnnotationButton");
  const dropdown = document.getElementById("mobileAnnotationDropdown");
  if (!control || !button || !dropdown) return;

  control.hidden = mobileAnnotationState.files.length === 0;
  button.disabled = mobileAnnotationState.busy;
  button.setAttribute("aria-busy", String(mobileAnnotationState.busy));
  const groupDropdown = document.getElementById("groupDropdown");
  const sampleDropdown = document.getElementById("sampleDropdown");
  if (groupDropdown) groupDropdown.disabled = mobileAnnotationState.busy;
  if (sampleDropdown) sampleDropdown.disabled = mobileAnnotationState.busy;
  button.textContent = mobileAnnotationState.busy
    ? "Loading Annotations…"
    : !mobileAnnotationState.loaded
      ? "Load Annotations"
      : mobileAnnotationState.visible
        ? "Hide Annotations"
        : "Show Annotations";
  button.setAttribute(
    "aria-expanded",
    String(!dropdown.hidden && mobileAnnotationState.files.length > 1),
  );
}

function configureMobileAnnotationControl(files) {
  if (!mobileMode) return;
  mobileAnnotationState.files = [...files];
  const button = document.getElementById("mobileAnnotationButton");
  const dropdown = document.getElementById("mobileAnnotationDropdown");
  if (!button || !dropdown) return;

  dropdown.innerHTML = "";
  files.forEach((file, index) => {
    const option = document.createElement("button");
    option.type = "button";
    option.textContent = getAnnotationFileLabel(file, index);
    option.title = file;
    option.addEventListener("click", async (event) => {
      event.preventDefault();
      event.stopPropagation();
      dropdown.hidden = true;
      await loadMobileAnnotations(file);
    });
    dropdown.appendChild(option);
  });

  button.onclick = async (event) => {
    event.preventDefault();
    event.stopPropagation();
    if (mobileAnnotationState.busy) return;
    if (mobileAnnotationState.loaded) {
      setMobileAnnotationsVisible(!mobileAnnotationState.visible);
      return;
    }
    if (mobileAnnotationState.files.length === 1) {
      await loadMobileAnnotations(mobileAnnotationState.files[0]);
      return;
    }
    dropdown.hidden = !dropdown.hidden;
    updateMobileAnnotationControl();
  };
  updateMobileAnnotationControl();
}

function setMobileAnnotationsVisible(visible) {
  if (!mobileMode || !mobileAnnotationState.loaded) return;
  mobileAnnotationState.visible = Boolean(visible);
  const showAnnotations = document.getElementById("show-annotations");
  const showLabels = document.getElementById("show-annotation-labels");
  if (showAnnotations) showAnnotations.checked = mobileAnnotationState.visible;
  if (showLabels) showLabels.checked = true;
  applyAnnotationVisibilityState();
  updateMobileAnnotationControl();
}

async function loadMobileAnnotations(file) {
  if (!mobileMode || mobileAnnotationState.busy) return;
  const requestedSampleIndex = currentIndex;
  mobileAnnotationState.busy = true;
  updateMobileAnnotationControl();

  try {
    const data = await fetchAnnotationJSON(file);
    if (currentIndex !== requestedSampleIndex) return;
    suppressUnsavedAnnotationTracking = true;
    clearAnnotations({ markUnsaved: false });
    await loadAnnotations(data, {
      groupMode: "preserve",
      selectImported: false,
      onProgress: () => {},
    });
    annotationHistory.reset();
    setUnsavedWork("annotations", false);
    mobileAnnotationState.loaded = true;
    mobileAnnotationState.file = file;
    setMobileAnnotationsVisible(true);
  } catch (error) {
    console.error("Error loading mobile annotations:", error);
    clearAnnotations({ markUnsaved: false });
    alert(error.message || "Could not load annotation GeoJSON.");
  } finally {
    suppressUnsavedAnnotationTracking = false;
    mobileAnnotationState.busy = false;
    updateMobileAnnotationControl();
  }
}

document.addEventListener("click", function (event) {
  const dropdown = document.getElementById("loadAnnoFromJSONDropdown");
  const button = document.getElementById("loadAnnoFromJSONButton");

  if (!dropdown || !button) return;

  if (!dropdown.contains(event.target) && event.target !== button) {
    dropdown.style.display = "none";
  }
});

document.addEventListener("click", function (event) {
  const dropdown = document.getElementById("mobileAnnotationDropdown");
  const button = document.getElementById("mobileAnnotationButton");
  if (!dropdown || !button || dropdown.hidden) return;
  if (!dropdown.contains(event.target) && event.target !== button) {
    dropdown.hidden = true;
    updateMobileAnnotationControl();
  }
});

function resetTileSetScrollIndices() {
  tileSetScrollIndices = tileSets().map(() => scrollIndex);
}

function getTileSetVisibleTileIndex(tileSetIndex) {
  const tiles = tileSets()[tileSetIndex]?.tiles || [];
  if (tiles.length === 0) return 0;

  const scrollValue = Number.isFinite(tileSetScrollIndices[tileSetIndex])
    ? tileSetScrollIndices[tileSetIndex]
    : scrollIndex;
  return ((scrollValue % tiles.length) + tiles.length) % tiles.length;
}

function getTileSetTypeLabel(tileSet) {
  const tileCount = tileSet?.tiles?.length || 0;
  if (tileCount <= 1) return "Individual";
  return tileSet.periodDegrees ? "Rotation" : "Multiple";
}

function cycleTileSetImage(tileSetIndex, direction) {
  const tileSet = tileSets()[tileSetIndex];
  if (!tileSet || tileSet.periodDegrees || (tileSet.tiles?.length || 0) <= 1) {
    return;
  }

  const currentValue = Number.isFinite(tileSetScrollIndices[tileSetIndex])
    ? tileSetScrollIndices[tileSetIndex]
    : scrollIndex;
  tileSetScrollIndices[tileSetIndex] = currentValue + direction;
  displayImages();
  updateImageCheckboxLabels();
}

function canCycleTileSet(tileSet) {
  return Boolean(
    tileSet && !tileSet.periodDegrees && (tileSet.tiles?.length || 0) > 1,
  );
}

function cycleAllMultipleTileSetImages(direction) {
  let changed = false;
  tileSets().forEach((tileSet, index) => {
    if (!canCycleTileSet(tileSet)) return;
    const currentValue = Number.isFinite(tileSetScrollIndices[index])
      ? tileSetScrollIndices[index]
      : scrollIndex;
    tileSetScrollIndices[index] = currentValue + direction;
    changed = true;
  });

  if (!changed) return false;
  displayImages();
  updateImageCheckboxLabels();
  return true;
}

// Function to update the image checkbox labels based on tileLabels array
function updateImageCheckboxLabels() {
  const checkboxes = document.querySelectorAll(".image-checkbox");

  checkboxes.forEach((checkbox, i) => {
    const label = checkbox.parentElement?.querySelector(
      ".image-checkbox-label",
    );
    const typeBadge = checkbox.parentElement?.parentElement?.querySelector(
      ".tile-set-type-badge",
    );
    const cycleControls = checkbox.parentElement?.parentElement?.querySelector(
      ".tile-set-cycle-controls",
    );
    const tileSet = tileSets()[i];
    if (!tileSet || !label) return;

    const tiles = tileSet.tiles;
    if (!tiles || tiles.length === 0) return;

    const visibleTileIndex = getTileSetVisibleTileIndex(i);
    const tileLabel = tiles[visibleTileIndex]?.label;

    label.textContent = tileLabel || tileSet.label || `Img ${i + 1}`;
    if (typeBadge) {
      typeBadge.textContent = getTileSetTypeLabel(tileSet);
      typeBadge.title =
        tileSet.periodDegrees && tiles.length > 1
          ? "Multiple images linked to rotation"
          : tiles.length > 1
            ? "Multiple images selected one at a time"
            : "Single image tile set";
    }
    if (cycleControls) {
      cycleControls.hidden =
        Boolean(tileSet.periodDegrees) || tiles.length <= 1;
    }
  });

  refreshPorosityTileSetLabels();
}

function toggleOnImages() {
  const checkboxes = document.querySelectorAll(".image-checkbox");
  const count = tileSets().length;
  resetTileSetScrollIndices();

  checkboxes.forEach((checkbox, i) => {
    if (i < count) {
      checkbox.checked = i === 0;
    }
  });

  displayImages();
}

// TODO: Only select the first image upon first load (not currently working
// because the image is undefined when toggleImage() is called)
function deselectAllButFirstImage() {
  for (let i = 1; i <= 4; i++) {
    const checkbox = document.getElementById(`image${i}`);
    if (checkbox) {
      if (i > 1 && checkbox.checked === true) {
        toggleImage(checkbox, i);
      }
    }
  }
}

// Function to update the label dynamically for opacity sliders
function updateOpacitySliderLabels() {
  const sliderRows = document.querySelectorAll(
    "#checkboxOpacityContainer > div",
  );

  sliderRows.forEach((row, i) => {
    const label = row.querySelector("label");
    const tileSet = tileSets()[i];

    if (!tileSet) {
      row.style.display = "none";
      return;
    }

    row.style.display = "";
    label.textContent = tileSet.label || `Img ${i + 1}`;
  });
}

function getTileSetDisplayLabel(tileSet, index) {
  return tileSet?.label || `Img ${index + 1}`;
}

function normalizeAppearanceValue(key, value) {
  const numericValue = Number(value);
  const fallback = TILE_SET_APPEARANCE_DEFAULTS[key];
  if (!Number.isFinite(numericValue)) return fallback;

  switch (key) {
    case "brightness":
    case "contrast":
    case "saturation":
      return Math.max(0, Math.min(300, Math.round(numericValue)));
    case "hue":
      return Math.max(-180, Math.min(180, Math.round(numericValue)));
    default:
      return fallback;
  }
}

function getTileSetAppearance(tileSet) {
  if (!tileSet) return { ...TILE_SET_APPEARANCE_DEFAULTS };
  const existing = tileSetAppearanceState.get(tileSet);
  if (existing) return existing;

  const appearance = { ...TILE_SET_APPEARANCE_DEFAULTS };
  tileSetAppearanceState.set(tileSet, appearance);
  return appearance;
}

function normalizeTransformValue(key, value) {
  const fallback = TILE_SET_TRANSFORM_DEFAULTS[key];
  const stringValue = String(value ?? fallback);
  const valueKey = stringValue.trim();
  switch (key) {
    case "recipeType":
      return ["simple", "raster", "polarization"].includes(valueKey)
        ? valueKey
        : fallback;
    case "type":
      return [
        "none",
        "sobel",
        "laplacian",
        "unsharp",
        "localContrast",
        "emboss",
        "channelMap",
      ].includes(valueKey)
        ? valueKey
        : fallback;
    case "output":
      return ["grayscale", "falseColor", "rgb", "classification"].includes(valueKey)
        ? valueKey
        : fallback;
    case "channel":
      return [
        "red",
        "green",
        "blue",
        "luminance",
        "saturation",
        "hue",
      ].includes(valueKey)
        ? valueKey
        : fallback;
    case "rasterExpression":
      return stringValue.trim().replace(/\s+/g, " ").slice(0, 200) || fallback;
    case "rasterNormalize":
      return value !== false && value !== "false";
    case "rasterScale":
      return ["auto", "signed", "unit", "raw", "custom"].includes(valueKey)
        ? valueKey
        : fallback;
    case "rasterCustomMin":
    case "rasterCustomMax": {
      const numericValue = Number(value);
      return Number.isFinite(numericValue) ? numericValue : fallback;
    }
    case "polarizationPplIndex":
    case "polarizationXplIndex":
    case "polarizationCplIndex": {
      const numericValue = Number.parseInt(value, 10);
      return Number.isFinite(numericValue) ? numericValue : -1;
    }
    case "polarizationProduct":
      return PetroPolarizationAnalysis?.getProductDefinition?.(valueKey)
        ? valueKey
        : fallback;
    case "polarizationColormap":
      return [
        "viridis",
        "inferno",
        "turbo",
        "blues",
        "gray",
        "hue",
        "hue_shifted",
        "twilight",
        "twilight_shifted",
        "diverging",
      ].includes(valueKey)
        ? valueKey
        : fallback;
    case "polarizationClassificationPreset":
      return ["conservative", "balanced", "sensitive", "custom"].includes(valueKey)
        ? valueKey
        : fallback;
    case "polarizationLowTransmission":
    case "polarizationXplExtinctionCeiling":
    case "polarizationPplAbsoluteThreshold": {
      const numericValue = Number(value);
      return Number.isFinite(numericValue)
        ? Math.max(0, Math.min(255, numericValue))
        : fallback;
    }
    case "polarizationPplThreshold":
    case "polarizationXplThreshold":
    case "polarizationMaxFitError": {
      const numericValue = Number(value);
      return Number.isFinite(numericValue)
        ? Math.max(0.001, Math.min(2, numericValue))
        : fallback;
    }
    case "polarizationMinConfidence": {
      const numericValue = Number(value);
      return Number.isFinite(numericValue)
        ? Math.max(0, Math.min(1, numericValue))
        : fallback;
    }
    case "intensity": {
      const numericValue = Number(value);
      return Number.isFinite(numericValue)
        ? Math.max(0, Math.min(3, numericValue))
        : fallback;
    }
    case "radius": {
      const numericValue = Number(value);
      return Number.isFinite(numericValue)
        ? Math.max(1, Math.min(8, Math.round(numericValue)))
        : fallback;
    }
    default:
      return fallback;
  }
}

function normalizeTileSetTransform(transform = {}) {
  const legacyRasterNormalize = normalizeTransformValue(
    "rasterNormalize",
    transform.rasterNormalize,
  );
  const rasterScale = legacyRasterNormalize
    ? "auto"
    : normalizeTransformValue("rasterScale", transform.rasterScale);
  return {
    recipeType: normalizeTransformValue("recipeType", transform.recipeType),
    type: normalizeTransformValue("type", transform.type),
    intensity: normalizeTransformValue("intensity", transform.intensity),
    radius: normalizeTransformValue("radius", transform.radius),
    output: normalizeTransformValue("output", transform.output),
    channel: normalizeTransformValue("channel", transform.channel),
    rasterExpression: normalizeTransformValue(
      "rasterExpression",
      transform.rasterExpression,
    ),
    rasterNormalize: rasterScale === "auto",
    rasterScale,
    rasterCustomMin: normalizeTransformValue(
      "rasterCustomMin",
      transform.rasterCustomMin,
    ),
    rasterCustomMax: normalizeTransformValue(
      "rasterCustomMax",
      transform.rasterCustomMax,
    ),
    polarizationPplIndex: normalizeTransformValue(
      "polarizationPplIndex",
      transform.polarizationPplIndex,
    ),
    polarizationXplIndex: normalizeTransformValue(
      "polarizationXplIndex",
      transform.polarizationXplIndex,
    ),
    polarizationCplIndex: normalizeTransformValue(
      "polarizationCplIndex",
      transform.polarizationCplIndex,
    ),
    polarizationProduct: normalizeTransformValue(
      "polarizationProduct",
      transform.polarizationProduct,
    ),
    polarizationColormap: normalizeTransformValue(
      "polarizationColormap",
      transform.polarizationColormap,
    ),
    polarizationClassificationPreset: normalizeTransformValue(
      "polarizationClassificationPreset",
      transform.polarizationClassificationPreset,
    ),
    polarizationLowTransmission: normalizeTransformValue(
      "polarizationLowTransmission",
      transform.polarizationLowTransmission,
    ),
    polarizationXplExtinctionCeiling: normalizeTransformValue(
      "polarizationXplExtinctionCeiling",
      transform.polarizationXplExtinctionCeiling,
    ),
    polarizationPplThreshold: normalizeTransformValue(
      "polarizationPplThreshold",
      transform.polarizationPplThreshold,
    ),
    polarizationPplAbsoluteThreshold: normalizeTransformValue(
      "polarizationPplAbsoluteThreshold",
      transform.polarizationPplAbsoluteThreshold,
    ),
    polarizationXplThreshold: normalizeTransformValue(
      "polarizationXplThreshold",
      transform.polarizationXplThreshold,
    ),
    polarizationMaxFitError: normalizeTransformValue(
      "polarizationMaxFitError",
      transform.polarizationMaxFitError,
    ),
    polarizationMinConfidence: normalizeTransformValue(
      "polarizationMinConfidence",
      transform.polarizationMinConfidence,
    ),
  };
}

function getTileSetTransform(tileSet) {
  if (!tileSet) return { ...TILE_SET_TRANSFORM_DEFAULTS };
  const existing = tileSetTransformState.get(tileSet);
  if (existing) return existing;

  const transform = { ...TILE_SET_TRANSFORM_DEFAULTS };
  tileSetTransformState.set(tileSet, transform);
  return transform;
}

function isDefaultTileSetTransform(tileSet) {
  const transform = getTileSetTransform(tileSet);
  return (
    transform.recipeType === TILE_SET_TRANSFORM_DEFAULTS.recipeType &&
    transform.type === TILE_SET_TRANSFORM_DEFAULTS.type
  );
}

function shouldProcessTileSet(tileSet) {
  const transform = getTileSetTransform(tileSet);
  const rawTileTransformActive =
    !isDefaultTileSetTransform(tileSet) &&
    !isRasterRecipe(transform) &&
    !isPolarizationRecipe(transform);
  return !isDefaultTileSetAppearance(tileSet) || rawTileTransformActive;
}

function getSelectedTransformTileSetIndex() {
  const rawIndex = Number.parseInt(transformTileSetSelect?.value || "0", 10);
  if (!Number.isFinite(rawIndex)) return 0;
  return Math.min(Math.max(rawIndex, 0), Math.max(tileSets().length - 1, 0));
}

function getTransformMode() {
  return "preview";
}

function getSelectedTransformRecipeType() {
  return (
    document.querySelector('input[name="transformImageryRecipe"]:checked')
      ?.value || "simple"
  );
}

function isTransformPreviewEnabled() {
  return transformPreviewEnabled?.checked !== false;
}

function isChannelTransform(type) {
  return type === "channelMap";
}

function isRasterRecipe(transform) {
  return transform?.recipeType === "raster";
}

function isPolarizationRecipe(transform) {
  return transform?.recipeType === "polarization";
}

function getTransformTypeLabel(type) {
  switch (type) {
    case "sobel":
      return "Sobel Edge";
    case "laplacian":
      return "Laplacian Edge";
    case "unsharp":
      return "Unsharp Mask";
    case "localContrast":
      return "Local Contrast";
    case "emboss":
      return "Emboss Relief";
    case "channelMap":
      return "Channel Map";
    default:
      return "Transform";
  }
}

function syncRasterCustomRangeInputsFromState() {
  if (transformRasterCustomMinInput) {
    transformRasterCustomMinInput.value = formatTransformTooltipNumber(
      transformRasterCustomRange.min,
    );
  }
  if (transformRasterCustomMaxInput) {
    transformRasterCustomMaxInput.value = formatTransformTooltipNumber(
      transformRasterCustomRange.max,
    );
  }
}

function syncRasterCustomRangeFromInputs(options = {}) {
  const minValue = Number(transformRasterCustomMinInput?.value);
  const maxValue = Number(transformRasterCustomMaxInput?.value);
  if (!Number.isFinite(minValue)) {
    if (options.showErrors)
      setTransformStatus("Enter a numeric minimum value.", "error");
    return false;
  }
  if (!Number.isFinite(maxValue)) {
    if (options.showErrors)
      setTransformStatus("Enter a numeric maximum value.", "error");
    return false;
  }
  if (maxValue <= minValue) {
    if (options.showErrors) {
      setTransformStatus(
        "Custom output maximum must be greater than the minimum.",
        "error",
      );
    }
    return false;
  }

  transformRasterCustomRange = {
    min: minValue,
    max: maxValue,
  };
  return true;
}

function getTransformOptionsFromControls() {
  const recipeType = getSelectedTransformRecipeType();
  if (recipeType === "polarization") {
    return normalizeTileSetTransform({
      ...TILE_SET_TRANSFORM_DEFAULTS,
      recipeType: "polarization",
      output: transformOutputSelect?.value || "falseColor",
      channel: transformChannelSelect?.value || "luminance",
      polarizationPplIndex: transformPolarizationPplSelect?.value ?? -1,
      polarizationXplIndex: transformPolarizationXplSelect?.value ?? -1,
      polarizationCplIndex: transformPolarizationCplSelect?.value ?? -1,
      polarizationProduct:
        transformPolarizationProductSelect?.value || "ppl_modulation",
      polarizationColormap:
        transformPolarizationColormap?.value || "viridis",
      polarizationClassificationPreset:
        transformPolarizationClassificationPreset?.value || "balanced",
      polarizationLowTransmission:
        transformPolarizationLowTransmission?.value ?? 15,
      polarizationXplExtinctionCeiling:
        transformPolarizationXplExtinctionCeiling?.value ?? 12,
      polarizationPplThreshold:
        transformPolarizationPplThreshold?.value ?? 0.08,
      polarizationPplAbsoluteThreshold:
        transformPolarizationPplAbsoluteThreshold?.value ?? 4,
      polarizationXplThreshold:
        transformPolarizationXplThreshold?.value ?? 0.15,
      polarizationMaxFitError:
        transformPolarizationMaxFitError?.value ?? 0.12,
      polarizationMinConfidence:
        transformPolarizationMinConfidence?.value ?? 0.35,
    });
  }
  if (recipeType === "raster") {
    if (transformRasterScaleSelect?.value === "custom") {
      syncRasterCustomRangeFromInputs();
    }
    const rasterScale = transformRasterScaleSelect?.value || "auto";
    return normalizeTileSetTransform({
      ...TILE_SET_TRANSFORM_DEFAULTS,
      recipeType: "raster",
      output: transformOutputSelect?.value || "grayscale",
      rasterExpression:
        getRasterExpressionText() ||
        TILE_SET_TRANSFORM_DEFAULTS.rasterExpression,
      rasterNormalize: rasterScale === "auto",
      rasterScale,
      rasterCustomMin: transformRasterCustomRange.min,
      rasterCustomMax: transformRasterCustomRange.max,
      polarizationColormap:
        transformPolarizationColormap?.value || "viridis",
    });
  }

  return normalizeTileSetTransform({
    recipeType: "simple",
    type: transformTypeSelect?.value || "none",
    intensity: transformIntensity?.value || 1,
    radius: transformRadius?.value || 2,
    output: transformOutputSelect?.value || "grayscale",
    channel: transformChannelSelect?.value || "luminance",
    polarizationColormap:
      transformPolarizationColormap?.value || "viridis",
  });
}

function normalizeRasterTokenChannel(channel) {
  const value = String(channel || "").toLowerCase();
  if (TRANSFORM_RASTER_CHANNELS[value]) return value;
  const entry = Object.entries(TRANSFORM_RASTER_CHANNELS).find(
    ([, channelName]) => channelName === value,
  );
  return entry?.[0] || "l";
}

function isRecognizedRasterChannelToken(channel) {
  const value = String(channel || "").toLowerCase();
  return (
    Boolean(TRANSFORM_RASTER_CHANNELS[value]) ||
    Object.values(TRANSFORM_RASTER_CHANNELS).includes(value)
  );
}

function getRasterInputSymbol(index) {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  if (index < alphabet.length) return alphabet[index];
  return `T${index + 1}`;
}

function getRasterInputTileSetEntries() {
  return tileSets()
    .map((tileSet, tileSetIndex) => ({
      symbol: getRasterInputSymbol(tileSetIndex),
      tileSet,
      tileSetIndex,
    }))
    .filter((entry) => entry.tileSet);
}

function getRasterInputEntry(symbol) {
  const normalizedSymbol = String(symbol || "").toUpperCase();
  return getRasterInputTileSetEntries().find(
    (entry) => entry.symbol === normalizedSymbol,
  );
}

function getRasterExpressionText() {
  return String(transformRasterCustomExpression?.value || "").trim();
}

function setRasterCalculatorExpression(value) {
  if (!transformRasterCustomExpression) return;
  transformRasterCustomExpression.value = String(value ?? "");
  transformRasterCustomExpression.dataset.userEdited = "true";
}

function isAllowedRasterExpressionKeyboardInput(event) {
  if (!event || event.isComposing) return false;
  if (event.inputType && event.inputType.startsWith("delete")) {
    return true;
  }
  if (event.inputType && event.inputType !== "insertText") return false;
  return /^[0-9+\-*/().,\s]+$/.test(event.data || "");
}

function focusRasterCalculatorExpression(start = null, end = null) {
  if (!transformRasterCustomExpression) return;
  transformRasterCustomExpression.focus();
  const length = transformRasterCustomExpression.value.length;
  const selectionStart =
    start === null ? length : Math.max(0, Math.min(length, start));
  const selectionEnd =
    end === null ? selectionStart : Math.max(0, Math.min(length, end));
  transformRasterCustomExpression.setSelectionRange(
    selectionStart,
    selectionEnd,
  );
}

function insertRasterCalculatorText(text, selectOffset = 0) {
  if (!transformRasterCustomExpression) return;
  const input = transformRasterCustomExpression;
  const value = input.value || "";
  const start = input.selectionStart ?? value.length;
  const end = input.selectionEnd ?? start;
  const nextValue = `${value.slice(0, start)}${text}${value.slice(end)}`;
  setRasterCalculatorExpression(nextValue);
  const cursor = start + text.length + selectOffset;
  focusRasterCalculatorExpression(cursor, cursor);
  updateTransformAdvancedExpressionStatus();
}

function deleteRasterCalculatorSelection(direction = "backward") {
  if (!transformRasterCustomExpression) return;
  const input = transformRasterCustomExpression;
  const value = input.value || "";
  const start = input.selectionStart ?? value.length;
  const end = input.selectionEnd ?? start;

  if (start !== end) {
    setRasterCalculatorExpression(
      `${value.slice(0, start)}${value.slice(end)}`,
    );
    focusRasterCalculatorExpression(start, start);
  } else if (direction === "forward" && start < value.length) {
    setRasterCalculatorExpression(
      `${value.slice(0, start)}${value.slice(start + 1)}`,
    );
    focusRasterCalculatorExpression(start, start);
  } else if (direction !== "forward" && start > 0) {
    setRasterCalculatorExpression(
      `${value.slice(0, start - 1)}${value.slice(start)}`,
    );
    focusRasterCalculatorExpression(start - 1, start - 1);
  }

  updateTransformAdvancedExpressionStatus();
}

function insertRasterInputToken(inputName, channel) {
  const normalizedInput = String(inputName || "A").toUpperCase();
  const normalizedChannel = normalizeRasterTokenChannel(channel);
  insertRasterCalculatorText(`${normalizedInput}.${normalizedChannel}`);
}

function insertRasterBuilderFunction(functionName) {
  const normalizedName = String(functionName || "").toLowerCase();
  if (!normalizedName) return;

  if (normalizedName === "normdiff") {
    insertRasterCalculatorText("normdiff(,)", -2);
    return;
  }

  insertRasterCalculatorText(`${normalizedName}()`, -1);
}

function tokenizeRasterExpression(expression) {
  const tokens = [];
  let index = 0;
  const text = String(expression || "");

  while (index < text.length) {
    const char = text[index];
    if (/\s/.test(char)) {
      index += 1;
      continue;
    }

    if ("+-*/(),".includes(char)) {
      tokens.push({ type: char, value: char, start: index, end: index + 1 });
      index += 1;
      continue;
    }

    const numberMatch = /^\d+(?:\.\d+)?/.exec(text.slice(index));
    if (numberMatch) {
      tokens.push({
        type: "number",
        value: Number(numberMatch[0]),
        start: index,
        end: index + numberMatch[0].length,
      });
      index += numberMatch[0].length;
      continue;
    }

    const variableMatch = /^([A-Z]|T\d+)\.([A-Za-z]+)/i.exec(text.slice(index));
    if (variableMatch) {
      const rawValue = variableMatch[0];
      tokens.push({
        type: "variable",
        set: variableMatch[1].toUpperCase(),
        channel: variableMatch[2].toLowerCase(),
        value: rawValue,
        start: index,
        end: index + rawValue.length,
      });
      index += rawValue.length;
      continue;
    }

    const identifierMatch = /^[A-Za-z_][A-Za-z0-9_]*/.exec(text.slice(index));
    if (identifierMatch) {
      tokens.push({
        type: "identifier",
        value: identifierMatch[0].toLowerCase(),
        start: index,
        end: index + identifierMatch[0].length,
      });
      index += identifierMatch[0].length;
      continue;
    }

    throw new Error(`Unexpected character "${char}".`);
  }

  return tokens;
}

function parseRasterExpressionTokens(tokens) {
  let index = 0;
  const peek = () => tokens[index] || null;
  const consume = (type = null) => {
    const token = peek();
    if (!token || (type && token.type !== type)) {
      throw new Error(
        type ? `Expected "${type}".` : "Unexpected end of expression.",
      );
    }
    index += 1;
    return token;
  };

  const parseExpression = () => parseAdditive();
  const parseAdditive = () => {
    let node = parseMultiplicative();
    while (peek()?.type === "+" || peek()?.type === "-") {
      const operator = consume().value;
      node = {
        type: "binary",
        operator,
        left: node,
        right: parseMultiplicative(),
      };
    }
    return node;
  };
  const parseMultiplicative = () => {
    let node = parseUnary();
    while (peek()?.type === "*" || peek()?.type === "/") {
      const operator = consume().value;
      node = {
        type: "binary",
        operator,
        left: node,
        right: parseUnary(),
      };
    }
    return node;
  };
  const parseUnary = () => {
    if (peek()?.type === "+" || peek()?.type === "-") {
      return {
        type: "unary",
        operator: consume().value,
        argument: parseUnary(),
      };
    }
    return parsePrimary();
  };
  const parsePrimary = () => {
    const token = peek();
    if (!token) throw new Error("Expression is incomplete.");

    if (token.type === "number") {
      consume();
      return { type: "number", value: token.value };
    }

    if (token.type === "variable") {
      consume();
      return {
        type: "variable",
        set: token.set,
        channel: normalizeRasterTokenChannel(token.channel),
        rawChannel: token.channel,
      };
    }

    if (token.type === "identifier") {
      const name = consume().value;
      consume("(");
      const args = [];
      if (peek()?.type !== ")") {
        args.push(parseExpression());
        while (peek()?.type === ",") {
          consume(",");
          args.push(parseExpression());
        }
      }
      consume(")");
      return { type: "function", name, args };
    }

    if (token.type === "(") {
      consume("(");
      const expression = parseExpression();
      consume(")");
      return expression;
    }

    throw new Error(`Unexpected token "${token.value}".`);
  };

  const ast = parseExpression();
  if (index < tokens.length) {
    throw new Error(`Unexpected token "${tokens[index].value}".`);
  }
  return ast;
}

function parseRasterExpressionAst(expression) {
  return parseRasterExpressionTokens(tokenizeRasterExpression(expression));
}

function getRasterVariableKey(node) {
  return `${node.set}.${node.channel}`;
}

function validateRasterExpressionAst(ast) {
  const visibleInputs = new Map();
  const aggregateInputs = new Map();
  const errors = [];

  const visit = (node, options = {}) => {
    if (!node) return;
    switch (node.type) {
      case "number":
        return;
      case "variable": {
        const inputEntry = getRasterInputEntry(node.set);
        if (!inputEntry) {
          errors.push(`${node.set} is not an available tile set.`);
        }
        if (!isRecognizedRasterChannelToken(node.rawChannel)) {
          errors.push(
            `${node.set}.${node.rawChannel} uses an unknown channel.`,
          );
        }
        const key = getRasterVariableKey(node);
        const input = {
          key,
          set: node.set,
          channel: node.channel,
          channelName: TRANSFORM_RASTER_CHANNELS[node.channel],
          tileSetIndex: inputEntry?.tileSetIndex ?? -1,
          tileSetLabel: inputEntry
            ? getSnapshotTileSetLabel(
                inputEntry.tileSet,
                inputEntry.tileSetIndex,
              )
            : node.set,
          tileCount: inputEntry?.tileSet?.tiles?.length || 0,
        };
        if (options.aggregateFunction) {
          aggregateInputs.set(`${options.aggregateFunction}:${key}`, {
            ...input,
            functionName: options.aggregateFunction,
            degenerate: input.tileCount <= 1,
          });
        } else {
          visibleInputs.set(key, input);
        }
        return;
      }
      case "unary":
        visit(node.argument, options);
        return;
      case "binary":
        visit(node.left, options);
        visit(node.right, options);
        return;
      case "function": {
        const isAggregate = TRANSFORM_RASTER_AGGREGATE_FUNCTIONS.includes(
          node.name,
        );
        const isScalar = TRANSFORM_RASTER_SCALAR_FUNCTIONS.includes(node.name);
        if (!isAggregate && !isScalar) {
          errors.push(`${node.name}() is not a supported function.`);
        }
        if (isAggregate) {
          if (node.args.length !== 1 || node.args[0]?.type !== "variable") {
            errors.push(`${node.name}() needs one input such as A.l.`);
          } else {
            visit(node.args[0], { aggregateFunction: node.name });
          }
          return;
        }
        if (node.name === "abs" && node.args.length !== 1) {
          errors.push("abs() needs one expression.");
        }
        if (node.name === "normdiff" && node.args.length !== 2) {
          errors.push("normdiff() needs two expressions.");
        }
        node.args.forEach((argument) => visit(argument, options));
        return;
      }
    }
  };

  visit(ast);
  return {
    valid: errors.length === 0,
    errors,
    visibleInputs: [...visibleInputs.values()],
    aggregateInputs: [...aggregateInputs.values()],
  };
}

function parseTransformRasterExpression(
  expression = getRasterExpressionText(),
) {
  const trimmedExpression = String(expression || "").trim();
  if (!trimmedExpression) {
    return {
      valid: false,
      expression: trimmedExpression,
      errors: ["Build an expression first."],
      ast: null,
      visibleInputs: [],
      aggregateInputs: [],
    };
  }

  try {
    const ast = parseRasterExpressionTokens(
      tokenizeRasterExpression(trimmedExpression),
    );
    return {
      expression: trimmedExpression,
      ast,
      ...validateRasterExpressionAst(ast),
    };
  } catch (error) {
    return {
      valid: false,
      expression: trimmedExpression,
      errors: [error.message || "Expression could not be parsed."],
      ast: null,
      visibleInputs: [],
      aggregateInputs: [],
    };
  }
}

function getTransformAdvancedExpressionPlan(
  expression = getRasterExpressionText(),
) {
  const parsed = parseTransformRasterExpression(expression);
  return {
    ...parsed,
    needsVisibleTiles: parsed.visibleInputs.length > 0,
    needsSourceStacks: parsed.aggregateInputs.length > 0,
  };
}

function getRasterEvaluationInputData(inputMap, setName) {
  const input = inputMap?.[setName];
  if (!input) return null;
  if (input.data) return input.data;
  return input;
}

function getRasterAggregateEvaluationKey(functionName, variableNode) {
  return `${functionName}:${getRasterVariableKey(variableNode)}`;
}

function evaluateRasterExpressionAstNode(
  node,
  inputMap,
  pixelOffset,
  aggregateValues = {},
) {
  switch (node?.type) {
    case "number":
      return node.value;
    case "variable": {
      const pixels = getRasterEvaluationInputData(inputMap, node.set);
      if (!pixels) {
        throw new Error(`${node.set} input data is not available.`);
      }
      return getChannelScalarValue(
        pixels,
        pixelOffset,
        TRANSFORM_RASTER_CHANNELS[node.channel],
      );
    }
    case "unary": {
      const value = evaluateRasterExpressionAstNode(
        node.argument,
        inputMap,
        pixelOffset,
        aggregateValues,
      );
      return node.operator === "-" ? -value : value;
    }
    case "binary": {
      const left = evaluateRasterExpressionAstNode(
        node.left,
        inputMap,
        pixelOffset,
        aggregateValues,
      );
      const right = evaluateRasterExpressionAstNode(
        node.right,
        inputMap,
        pixelOffset,
        aggregateValues,
      );
      switch (node.operator) {
        case "+":
          return left + right;
        case "-":
          return left - right;
        case "*":
          return left * right;
        case "/":
          return Math.abs(right) <= 0.0000001 ? 0 : left / right;
      }
      throw new Error(`${node.operator} is not supported.`);
    }
    case "function": {
      if (TRANSFORM_RASTER_AGGREGATE_FUNCTIONS.includes(node.name)) {
        const variableNode = node.args[0];
        const aggregateKey = getRasterAggregateEvaluationKey(
          node.name,
          variableNode,
        );
        if (
          Object.prototype.hasOwnProperty.call(aggregateValues, aggregateKey)
        ) {
          return aggregateValues[aggregateKey];
        }
        throw new Error(
          `${node.name}(${getRasterVariableKey(variableNode)}) stack data is not available.`,
        );
      }

      if (node.name === "abs") {
        return Math.abs(
          evaluateRasterExpressionAstNode(
            node.args[0],
            inputMap,
            pixelOffset,
            aggregateValues,
          ),
        );
      }

      if (node.name === "normdiff") {
        const left = evaluateRasterExpressionAstNode(
          node.args[0],
          inputMap,
          pixelOffset,
          aggregateValues,
        );
        const right = evaluateRasterExpressionAstNode(
          node.args[1],
          inputMap,
          pixelOffset,
          aggregateValues,
        );
        const denominator = left + right;
        return Math.abs(denominator) <= 0.0000001
          ? 0
          : (left - right) / denominator;
      }

      throw new Error(`${node.name}() is not supported.`);
    }
    default:
      throw new Error("Expression node is not supported.");
  }
}

function evaluateTransformRasterExpressionAtPixel(
  ast,
  inputMap,
  pixelOffset,
  aggregateValues = {},
) {
  try {
    return {
      ok: true,
      value: evaluateRasterExpressionAstNode(
        ast,
        inputMap,
        pixelOffset,
        aggregateValues,
      ),
    };
  } catch (error) {
    return {
      ok: false,
      error: error.message || "Expression could not be evaluated.",
    };
  }
}

function getRasterAggregateValuesForPixel(
  plan,
  aggregateInputMap,
  pixelOffset,
) {
  const values = {};
  const groupedInputs = new Map();
  (plan.aggregateInputs || []).forEach((input) => {
    const existing = groupedInputs.get(input.key);
    if (existing) {
      existing.functions.add(input.functionName);
    } else {
      groupedInputs.set(input.key, {
        ...input,
        functions: new Set([input.functionName]),
      });
    }
  });

  groupedInputs.forEach((input) => {
    const stack = aggregateInputMap?.[input.key] || [];
    if (!stack.length) return;

    let min = Infinity;
    let max = -Infinity;
    let sum = 0;
    let count = 0;
    stack.forEach((imageData) => {
      const pixels = imageData?.data || imageData;
      if (!pixels) return;
      const value = getChannelScalarValue(
        pixels,
        pixelOffset,
        TRANSFORM_RASTER_CHANNELS[input.channel],
      );
      if (!Number.isFinite(value)) return;
      min = Math.min(min, value);
      max = Math.max(max, value);
      sum += value;
      count += 1;
    });

    if (count === 0) return;
    for (const functionName of input.functions) {
      const aggregateKey = `${functionName}:${input.key}`;
      switch (functionName) {
        case "range":
          values[aggregateKey] = max - min;
          break;
        case "max":
          values[aggregateKey] = max;
          break;
        case "min":
          values[aggregateKey] = min;
          break;
        case "mean":
          values[aggregateKey] = sum / count;
          break;
      }
    }
  });
  return values;
}

function runTransformRasterEvaluatorSelfCheck() {
  const inputMap = {
    A: { data: new Uint8ClampedArray([100, 40, 20, 255]) },
    B: { data: new Uint8ClampedArray([25, 10, 5, 255]) },
  };
  const checks = [
    ["A.r", 100],
    ["A.l", getPixelLuminance(inputMap.A.data, 0)],
    ["abs(A.r - B.r)", 75],
    ["normdiff(A.r, B.r)", 0.6],
  ];
  const results = checks.map(([expression, expected]) => {
    const ast = parseRasterExpressionAst(expression);
    const result = evaluateTransformRasterExpressionAtPixel(ast, inputMap, 0);
    const passed = result.ok && Math.abs(result.value - expected) <= 0.000001;
    return {
      expression,
      expected,
      actual: result.value,
      passed,
      error: result.error || "",
    };
  });
  const aggregatePlan = {
    aggregateInputs: ["range", "max", "min", "mean"].map((functionName) => ({
      functionName,
      key: "A.l",
      channel: "l",
    })),
  };
  const aggregateValues = getRasterAggregateValuesForPixel(
    aggregatePlan,
    {
      "A.l": [
        { data: new Uint8ClampedArray([10, 10, 10, 255]) },
        { data: new Uint8ClampedArray([40, 40, 40, 255]) },
        { data: new Uint8ClampedArray([70, 70, 70, 255]) },
      ],
    },
    0,
  );
  [
    ["range(A.l)", 60],
    ["max(A.l)", 70],
    ["min(A.l)", 10],
    ["mean(A.l)", 40],
    ["A.r - mean(A.l)", 60],
  ].forEach(([expression, expected]) => {
    const ast = parseRasterExpressionAst(expression);
    const result = evaluateTransformRasterExpressionAtPixel(
      ast,
      inputMap,
      0,
      aggregateValues,
    );
    results.push({
      expression,
      expected,
      actual: result.value,
      passed: result.ok && Math.abs(result.value - expected) <= 0.000001,
      error: result.error || "",
    });
  });
  return {
    passed: results.every((result) => result.passed),
    results,
  };
}

if (typeof window !== "undefined") {
  window.runTransformRasterEvaluatorSelfCheck =
    runTransformRasterEvaluatorSelfCheck;
}

function getTransformAdvancedExpressionStatus(plan) {
  if (!plan.valid) return plan.errors[0] || "Expression is not valid.";
  const aggregateWarning = getTransformAggregateWarning(plan);
  if (aggregateWarning) return aggregateWarning;
  const visibleCount = plan.visibleInputs.length;
  const aggregateCount = plan.aggregateInputs.length;
  const degenerateCount = plan.aggregateInputs.filter(
    (input) => input.degenerate,
  ).length;
  const details = [
    `${visibleCount} visible input${visibleCount === 1 ? "" : "s"}`,
    `${aggregateCount} stack aggregate${aggregateCount === 1 ? "" : "s"}`,
  ];
  if (degenerateCount > 0) {
    details.push(
      `${degenerateCount} single-image aggregate${degenerateCount === 1 ? "" : "s"}`,
    );
  }
  return `Expression valid: ${details.join(", ")}.`;
}

function getTransformAggregateWarning(plan) {
  if (!plan?.valid || !plan.aggregateInputs?.length) return "";
  const degenerateRangeInput = plan.aggregateInputs.find(
    (input) => input.functionName === "range" && input.degenerate,
  );
  if (!degenerateRangeInput) return "";

  const alternative = getRasterInputTileSetEntries().find(
    (entry) =>
      entry.symbol !== degenerateRangeInput.set &&
      (entry.tileSet?.tiles?.length || 0) > 1,
  );
  const source = `${degenerateRangeInput.set}.${degenerateRangeInput.channel}`;
  const imageCount = Math.max(0, degenerateRangeInput.tileCount || 0);
  const countLabel = `${imageCount} image${imageCount === 1 ? "" : "s"}`;
  if (alternative) {
    return `${source} has ${countLabel}; range(${source}) will be 0. Try ${alternative.symbol}.${degenerateRangeInput.channel}.`;
  }
  return `${source} has ${countLabel}; range(${source}) will be 0.`;
}

function updateTransformAdvancedExpressionStatus() {
  if (!isRasterRecipe(getTransformOptionsFromControls())) return null;
  const plan = getTransformAdvancedExpressionPlan();
  setTransformStatus(
    getTransformAdvancedExpressionStatus(plan),
    plan.valid ? "ok" : "error",
  );
  return plan;
}

function planHasRenderableAdvancedExpression() {
  const plan = getTransformAdvancedExpressionPlan();
  return Boolean(plan.valid);
}

function updateAdvancedVisibleInputPreloadHints() {
  let requiredStackImageCount = 0;
  tileSets().forEach((tileSet) => {
    const transform = getTileSetTransform(tileSet);
    if (!isRasterRecipe(transform)) return;
    const plan = getTransformAdvancedExpressionPlan(transform.rasterExpression);
    if (!plan.valid) return;
    plan.aggregateInputs.forEach((input) => {
      const stackImageCount =
        tileSets()[input.tileSetIndex]?.tiles?.length || 0;
      requiredStackImageCount = Math.max(
        requiredStackImageCount,
        stackImageCount,
      );
    });
  });
  tileSets().forEach((tileSet) => {
    const transform = getTileSetTransform(tileSet);
    if (!isPolarizationRecipe(transform)) return;
    const polarizationStackImageCount = getPolarizationRequiredModalities(
      transform.polarizationProduct,
      transform,
    ).reduce((count, modality) => {
      return (
        count +
        (getPolarizationTileSet(modality, transform)?.tiles?.length || 0)
      );
    }, 0);
    requiredStackImageCount = Math.max(
      requiredStackImageCount,
      polarizationStackImageCount,
    );
  });
  const desiredCacheCount = Math.min(
    MAX_STACK_PREVIEW_TILE_CACHE_COUNT,
    Math.max(
      BASE_VIEWER_TILE_CACHE_COUNT,
      requiredStackImageCount * 100,
    ),
  );
  if (viewer?.tileCache) {
    viewer.maxImageCacheCount = desiredCacheCount;
    // OpenSeadragon 4.1 has no public setter for an existing cache.
    viewer.tileCache._maxImageCacheCount = desiredCacheCount;
  }
  tileSets().forEach((tileSet) => {
    (tileSet.tiles || []).forEach((tile) => {
      if (typeof tile.image?.setPreload === "function") {
        // Hidden advanced inputs are requested explicitly for the visible
        // destination coordinates. Broad OpenSeadragon preloading walks
        // unrelated pyramid tiles and repeatedly invalidates a settled
        // preview as each background tile arrives.
        tile.image.setPreload(false);
      }
    });
  });
}

function populateTransformRasterInputTable() {
  if (!transformRasterInputTableBody) return;
  transformRasterInputTableBody.innerHTML = "";
  const channels = [
    ["red", "r"],
    ["green", "g"],
    ["blue", "b"],
    ["luminance", "l"],
    ["saturation", "s"],
    ["hue", "h"],
  ];
  getRasterInputTileSetEntries().forEach((entry) => {
    const { symbol, tileSet, tileSetIndex } = entry;
    const row = document.createElement("tr");
    const heading = document.createElement("th");
    heading.textContent = symbol;
    heading.title = getSnapshotTileSetLabel(tileSet, tileSetIndex);
    row.append(heading);
    channels.forEach(([, label]) => {
      const cell = document.createElement("td");
      const button = document.createElement("button");
      button.type = "button";
      button.textContent = label;
      button.disabled = false;
      button.title = `${symbol}.${label} - ${getSnapshotTileSetLabel(tileSet, tileSetIndex)}`;
      button.addEventListener("click", function () {
        insertRasterInputToken(symbol, label);
      });
      cell.append(button);
      row.append(cell);
    });
    transformRasterInputTableBody.append(row);
  });
}

function updateDerivedPreviewProgress(progress) {
  if (!derivedPreviewOverlay?.state) return;
  const total = Math.max(progress.requested, 1);
  const completed = Math.min(progress.completed, total);
  const percent = Math.max(8, (completed / total) * 100);
  setTransformProgress(percent, `${completed}/${total} visible tiles calculated`);
  scheduleTransformHistogramRefresh();
  if (progress.requested > 0 && progress.pending === 0) {
    setTransformProgress(100, "Preview calculated");
    setTransformStatus(getTransformPreviewIdleStatus(derivedPreviewOverlay.state.tileSet), "ok");
  }
}

function getDerivedPreviewReferenceTile(tileSet) {
  const tileSetIndex = tileSets().indexOf(tileSet);
  const tiles = tileSet?.tiles || [];
  return tiles[getTileSetVisibleTileIndex(tileSetIndex)] || tiles[0] || null;
}

function getDerivedVisibleInputTile(tileSet, tileSetIndex) {
  const tiles = tileSet?.tiles || [];
  return tiles[getTileSetVisibleTileIndex(tileSetIndex)] || tiles[0] || null;
}

function getDerivedPreviewRequiredTiles(tileSet, transform, referenceTile) {
  const requiredTiles = new Set(referenceTile ? [referenceTile] : []);
  if (isRasterRecipe(transform)) {
    const plan = getTransformAdvancedExpressionPlan(transform.rasterExpression);
    plan.visibleInputs.forEach((input) => {
      const entry = getRasterInputEntry(input.set);
      const tile = getDerivedVisibleInputTile(
        entry?.tileSet,
        entry?.tileSetIndex,
      );
      if (tile) requiredTiles.add(tile);
    });
    plan.aggregateInputs.forEach((input) => {
      const entry = getRasterInputEntry(input.set);
      (entry?.tileSet?.tiles || []).forEach((tile) => requiredTiles.add(tile));
    });
  } else if (isPolarizationRecipe(transform)) {
    getPolarizationRequiredModalities(
      transform.polarizationProduct,
      transform,
    ).forEach(
      (modality) => {
        const sourceTileSet = getPolarizationTileSet(modality, transform);
        (sourceTileSet?.tiles || []).forEach((tile) => requiredTiles.add(tile));
      },
    );
  }
  return Array.from(requiredTiles);
}

function getMappedDerivedSourceCoordinates(
  referenceImage,
  sourceImage,
  level,
  x,
  y,
) {
  const referenceSource = referenceImage?.source;
  const source = sourceImage?.source;
  if (!referenceSource || !source) return null;
  const referenceMaxLevel = getTiledImageMaxLevel(referenceImage);
  const sourceMaxLevel = getTiledImageMaxLevel(sourceImage);
  if (!Number.isFinite(sourceMaxLevel)) return null;
  const sourceLevel = Math.min(
    sourceMaxLevel,
    Math.max(
      Number(source.minLevel) || 0,
      level +
        (Number.isFinite(referenceMaxLevel)
          ? sourceMaxLevel - referenceMaxLevel
          : 0),
    ),
  );
  const referenceBounds = referenceSource.getTileBounds(level, x, y);
  const center = referenceBounds?.getCenter?.() ||
    new OpenSeadragon.Point(
      referenceBounds.x + referenceBounds.width / 2,
      referenceBounds.y + referenceBounds.height / 2,
    );
  const coordinates = source.getTileAtPoint(sourceLevel, center);
  if (!coordinates) return null;
  const tileCount = source.getNumTiles(sourceLevel);
  return {
    level: sourceLevel,
    x: Math.max(0, Math.min(tileCount.x - 1, coordinates.x)),
    y: Math.max(0, Math.min(tileCount.y - 1, coordinates.y)),
  };
}

function downloadDerivedSourceTile(tile, coordinates, signal) {
  const image = tile?.image;
  const source = image?.source;
  if (!image || !source || !coordinates) {
    return Promise.reject(new Error("A source image is not ready."));
  }
  const src = source.getTileUrl(
    coordinates.level,
    coordinates.x,
    coordinates.y,
  );
  const postData = source.getTilePostData?.(
    coordinates.level,
    coordinates.x,
    coordinates.y,
  );
  const ajaxHeaders = source.getTileAjaxHeaders?.(
    coordinates.level,
    coordinates.x,
    coordinates.y,
  );
  return new Promise((resolve, reject) => {
    let settled = false;
    const job = {
      src,
      tile: coordinates,
      userData: {},
      postData,
      loadWithAjax: Boolean(image.loadTilesWithAjax),
      ajaxHeaders,
      crossOriginPolicy: image.crossOriginPolicy,
      ajaxWithCredentials: image.ajaxWithCredentials,
      finish(data, request, error) {
        if (settled) return;
        settled = true;
        signal?.removeEventListener("abort", abort);
        if (!data || error) {
          reject(new Error(error || `Could not load ${src}.`));
          return;
        }
        resolve(data);
      },
    };
    const abort = () => {
      if (settled) return;
      settled = true;
      source.downloadTileAbort?.(job);
      reject(new DOMException("Canceled", "AbortError"));
    };
    if (signal?.aborted) {
      abort();
      return;
    }
    signal?.addEventListener("abort", abort, { once: true });
    source.downloadTileStart(job);
  });
}

function getDerivedSourceCacheKey(tile, coordinates) {
  return `${tile?.uri || tile?.label || "tile"}:${coordinates?.level}/${coordinates?.x}/${coordinates?.y}`;
}

function createDerivedRasterTileContext(
  transform,
  outputTileSet,
  outputContext,
  tileContexts,
  autoScaleRange = null,
) {
  const plan = getTransformAdvancedExpressionPlan(transform.rasterExpression);
  if (!plan.valid || !plan.ast) {
    throw new Error(plan.errors[0] || "The expression is not renderable.");
  }
  const width = outputContext.canvas.width;
  const height = outputContext.canvas.height;
  const inputMap = {};
  const aggregateInputMap = {};
  plan.visibleInputs.forEach((input) => {
    const entry = getRasterInputEntry(input.set);
    const tile = getDerivedVisibleInputTile(
      entry?.tileSet,
      entry?.tileSetIndex,
    );
    const imageData = getContextImageDataMatchingSize(
      tileContexts.get(tile),
      width,
      height,
    );
    if (!imageData) throw new Error(`Waiting for ${input.set} source tile.`);
    inputMap[input.set] = imageData;
  });
  plan.aggregateInputs.forEach((input) => {
    if (aggregateInputMap[input.key]) return;
    const entry = getRasterInputEntry(input.set);
    const stack = (entry?.tileSet?.tiles || []).map((tile) =>
      getContextImageDataMatchingSize(tileContexts.get(tile), width, height),
    );
    if (!stack.length || stack.some((imageData) => !imageData)) {
      throw new Error(`Waiting for ${input.set} source stack.`);
    }
    aggregateInputMap[input.key] = stack;
  });

  const values = new Float32Array(width * height);
  let minValue = Infinity;
  let maxValue = -Infinity;
  for (let offset = 0, valueIndex = 0; offset < width * height * 4; offset += 4, valueIndex += 1) {
    const result = evaluateTransformRasterExpressionAtPixel(
      plan.ast,
      inputMap,
      offset,
      getRasterAggregateValuesForPixel(plan, aggregateInputMap, offset),
    );
    if (!result.ok) throw new Error(result.error);
    const value = Number(result.value);
    values[valueIndex] = Number.isFinite(value) ? value : 0;
    minValue = Math.min(minValue, values[valueIndex]);
    maxValue = Math.max(maxValue, values[valueIndex]);
  }

  const context = createCanvasContextFromImage(outputContext.canvas, {
    forceOpaque: true,
  });
  const imageData = context.createImageData(width, height);
  const output = imageData.data;
  const displayMin = Number.isFinite(autoScaleRange?.min)
    ? autoScaleRange.min
    : minValue;
  const displayMax = Number.isFinite(autoScaleRange?.max)
    ? autoScaleRange.max
    : maxValue;
  for (let offset = 0, valueIndex = 0; offset < output.length; offset += 4, valueIndex += 1) {
    const displayValue = clampColorValue(
      mapAdvancedRasterValue(
        values[valueIndex],
        transform,
        displayMin,
        displayMax,
      ),
    );
    const rgb = transform.output === "falseColor"
      ? getTransformColorMapRgb(displayValue, transform)
      : [displayValue, displayValue, displayValue];
    output[offset] = rgb[0];
    output[offset + 1] = rgb[1];
    output[offset + 2] = rgb[2];
    output[offset + 3] = 255;
  }
  context.putImageData(imageData, 0, 0);
  context.petroImageGeneratedPreviewContext = true;
  context.petroImageAdvancedRawValues = values;
  context.petroImageAdvancedRawWidth = width;
  context.petroImageAdvancedRawHeight = height;
  context.petroImageAdvancedAutoScaleRange = autoScaleRange;
  return context;
}

function createDerivedPolarizationTileContext(
  transform,
  outputContext,
  tileContexts,
) {
  const width = outputContext.canvas.width;
  const height = outputContext.canvas.height;
  const stacks = {};
  getPolarizationRequiredModalities(
    transform.polarizationProduct,
    transform,
  ).forEach(
    (modality) => {
      const sourceTileSet = getPolarizationTileSet(modality, transform);
      const stack = (sourceTileSet?.tiles || []).map((tile) => {
        const imageData = getContextImageDataMatchingSize(
          tileContexts.get(tile),
          width,
          height,
        );
        return imageData?.data;
      });
      if (!stack.length || stack.some((data) => !data)) {
        throw new Error(`Waiting for ${modality.toUpperCase()} source stack.`);
      }
      stacks[modality] = stack;
    },
  );
  const raster = PetroPolarizationAnalysis.calculatePolarizationRaster(
    stacks,
    width,
    height,
    {
      product: transform.polarizationProduct,
      channel: transform.channel,
      output: transform.output,
      classificationThresholds:
        getPolarizationClassificationThresholds(transform),
      pplAngles: getPolarizationAngles(getPolarizationTileSet("ppl", transform)),
      xplAngles: getPolarizationAngles(getPolarizationTileSet("xpl", transform)),
    },
  );
  const context = createCanvasContextFromImage(outputContext.canvas, {
    forceOpaque: true,
  });
  mapPolarizationRasterToImageData(context, raster, transform, {
    maskUnreliable: shouldMaskUnreliableAzimuthPreview(transform),
  });
  context.petroImageGeneratedPreviewContext = true;
  context.petroImageAdvancedRawValues = raster.values;
  context.petroImageAdvancedRgbValues = raster.rgbValues;
  context.petroImagePolarizationFitReliability = raster.fitReliability || null;
  context.petroImagePolarizationClassification = raster.classification || null;
  context.petroImageAdvancedRawWidth = width;
  context.petroImageAdvancedRawHeight = height;
  return context;
}

async function createDerivedPreviewTile(
  tileSet,
  transform,
  referenceTile,
  sourceCache,
  request,
  autoScaleRange = null,
) {
  if (request.signal.aborted) throw new DOMException("Canceled", "AbortError");
  const requiredTiles = getDerivedPreviewRequiredTiles(
    tileSet,
    transform,
    referenceTile,
  );
  const tileContexts = new Map();
  await Promise.all(
    requiredTiles.map(async (tile) => {
      const coordinates = getMappedDerivedSourceCoordinates(
        referenceTile.image,
        tile.image,
        request.level,
        request.x,
        request.y,
      );
      const cacheKey = getDerivedSourceCacheKey(tile, coordinates);
      let promise = sourceCache.get(cacheKey);
      if (!promise) {
        promise = downloadDerivedSourceTile(tile, coordinates, request.signal);
        sourceCache.set(cacheKey, promise);
        promise.catch(() => {
          if (sourceCache.get(cacheKey) === promise) sourceCache.delete(cacheKey);
        });
      }
      const data = await promise;
      if (request.signal.aborted) throw new DOMException("Canceled", "AbortError");
      const context = createCanvasContextFromImage(data, { forceOpaque: true });
      if (!context) throw new Error("Could not read a source tile.");
      tileContexts.set(tile, context);
    }),
  );
  const outputContext = tileContexts.get(referenceTile);
  if (!outputContext) throw new Error("The output source tile is unavailable.");
  const context = isPolarizationRecipe(transform)
    ? createDerivedPolarizationTileContext(transform, outputContext, tileContexts)
    : createDerivedRasterTileContext(
        transform,
        tileSet,
        outputContext,
        tileContexts,
        autoScaleRange,
      );
  const appearance = getTileSetAppearance(tileSet);
  if (!isDefaultAppearanceValue(appearance)) {
    applyTileSetAppearanceToContext(context, appearance);
  }
  markContextAsOpaqueTileContext(context);
  return context.canvas;
}

function getDerivedPreviewWorldIndex(tileSet) {
  const indices = (tileSet?.tiles || [])
    .map((tile) => viewer.world.getIndexOfItem(tile.image))
    .filter((index) => index >= 0);
  return indices.length
    ? Math.min(...indices)
    : viewer.world.getItemCount();
}

async function estimateAdvancedPreviewAutoScaleRange(transform) {
  const imageRect = getTransformGenerationImageRect();
  if (!imageRect) {
    throw new Error("Could not determine the image extent for auto-scaling.");
  }
  const maxPixels = 1000000;
  const maxSide = 2048;
  const sourcePixels = Math.max(1, imageRect.width * imageRect.height);
  const scale = Math.max(
    0.001,
    Math.min(
      1,
      Math.sqrt(maxPixels / sourcePixels),
      maxSide / Math.max(1, imageRect.width),
      maxSide / Math.max(1, imageRect.height),
    ),
  );
  const canvas = document.createElement("canvas");
  canvas.width = Math.max(1, Math.round(imageRect.width * scale));
  canvas.height = Math.max(1, Math.round(imageRect.height * scale));
  const context = canvas.getContext("2d", { willReadFrequently: true });
  if (!context) throw new Error("Could not create the auto-scale overview.");
  const result = await applyAdvancedTransformToExportContext(
    context,
    transform,
    imageRect,
    scale,
  );
  if (
    !Number.isFinite(result?.minValue) ||
    !Number.isFinite(result?.maxValue)
  ) {
    throw new Error("Could not calculate the global auto-scale range.");
  }
  return {
    min: result.minValue,
    max: result.maxValue,
    width: canvas.width,
    height: canvas.height,
    scale,
  };
}

async function startDerivedAdvancedPreview(tileSet, transform) {
  const referenceTile = getDerivedPreviewReferenceTile(tileSet);
  if (!referenceTile?.image) {
    setTransformStatus("Waiting for the selected source image...", "");
    return;
  }
  transformFitRequestGeneration += 1;
  const requestGeneration = transformFitRequestGeneration;
  transformFitSample = null;
  let autoScaleRange = null;
  try {
    if (
      isRasterRecipe(transform) &&
      (transform.rasterNormalize || transform.rasterScale === "auto")
    ) {
      setTransformStatus("Estimating the whole-image auto-scale range...");
      setTransformProgress(4, "Estimating global min/max...");
      autoScaleRange = await estimateAdvancedPreviewAutoScaleRange(transform);
      if (requestGeneration !== transformFitRequestGeneration) return;
      setTransformStatus(
        `Processing preview with global range ${formatTransformTooltipNumber(
          autoScaleRange.min,
        )} to ${formatTransformTooltipNumber(autoScaleRange.max)}...`,
      );
    }
    const sourceCache = new Map();
    const key = `${tileLoadGeneration}:${tileSets().indexOf(tileSet)}:${JSON.stringify(normalizeTileSetTransform(transform))}`;
    const state = await derivedPreviewOverlay.start({
      tileSet,
      key,
      referenceImage: referenceTile.image,
      worldIndex: getDerivedPreviewWorldIndex(tileSet),
      requestTile: (request) =>
        createDerivedPreviewTile(
          tileSet,
          transform,
          referenceTile,
          sourceCache,
          request,
          autoScaleRange,
        ),
    });
    state.petroImageSourceCache = sourceCache;
    state.petroImageReferenceTile = referenceTile;
    state.petroImageAutoScaleRange = autoScaleRange;
    displayImages();
    if (isPolarizationRecipe(transform)) {
      syncTransformFitControls(transform);
    }
    scheduleTransformFitRefresh();
    scheduleTransformHistogramRefresh();
    if (!isTransformPreviewEnabled()) {
      setTransformStatus(getTransformPreviewIdleStatus(tileSet));
    }
  } catch (error) {
    if (error?.name === "AbortError") return;
    setTransformStatus(error?.message || "Could not start preview.", "error");
  }
}

function stopDerivedAdvancedPreview() {
  transformFitRequestGeneration += 1;
  derivedPreviewOverlay?.stop();
  transformFitSample = null;
  renderTransformFitInspector();
  displayImages();
}

function applyRasterCalculatorPreview() {
  const tileSet = tileSets()[getSelectedTransformTileSetIndex()];
  const plan = updateTransformAdvancedExpressionStatus();
  if (!tileSet || !plan?.valid) {
    return;
  }

  const transform = getTransformOptionsFromControls();
  activeTransformPreviewSettings = { ...transform };
  resetTransformTileCaches(tileSet);
  tileSetTransformState.set(
    tileSet,
    transform,
  );
  updateSnapshotStatus();
  updateAdvancedVisibleInputPreloadHints();
  hideTransformValueTooltip();
  setTransformStatus("Processing preview...");
  setTransformPreviewProgressStart();
  updateTileSetAppearanceRenderingHints(tileSet);
  startDerivedAdvancedPreview(tileSet, transform);
  updateTransformControls();
  scheduleTransformHistogramRefresh();
}

function applyPolarizationPreview() {
  populateTransformPolarizationProducts();
  const transform = getTransformOptionsFromControls();
  if (hasDuplicatePolarizationRoleAssignments(transform)) {
    setTransformStatus("Assign each polarization role to a different tile set.", "error");
    return;
  }
  if (
    !getAvailablePolarizationProducts(transform).includes(
      transform.polarizationProduct,
    )
  ) {
    setTransformStatus(
      "The selected sources do not support this polarization product.",
      "error",
    );
    return;
  }
  const tileSet = tileSets()[getSelectedTransformTileSetIndex()];
  if (!tileSet) return;
  activeTransformPreviewSettings = { ...transform };
  resetTransformTileCaches(tileSet);
  tileSetTransformState.set(
    tileSet,
    transform,
  );
  updateAdvancedVisibleInputPreloadHints();
  hideTransformValueTooltip();
  setTransformStatus("Processing polarization preview...");
  setTransformPreviewProgressStart();
  updateTileSetAppearanceRenderingHints(tileSet);
  startDerivedAdvancedPreview(tileSet, transform);
  updateTransformControls();
  scheduleTransformHistogramRefresh();
}

function isSelectedAdvancedPreviewActive(recipeType) {
  const tileSet = tileSets()[getSelectedTransformTileSetIndex()];
  const transform = getTileSetTransform(tileSet);
  return transform.recipeType === recipeType && !isDefaultTileSetTransform(tileSet);
}

function stopSelectedAdvancedPreview(recipeType) {
  const tileSet = tileSets()[getSelectedTransformTileSetIndex()];
  if (!tileSet || !isSelectedAdvancedPreviewActive(recipeType)) return;

  activeTransformPreviewSettings = {
    ...getTransformOptionsFromControls(),
  };
  stopDerivedAdvancedPreview();
  tileSetTransformState.set(tileSet, { ...TILE_SET_TRANSFORM_DEFAULTS });
  updateTileSetAppearanceRenderingHints(tileSet);
  resetTransformTileCaches(tileSet);
  updateSnapshotStatus();
  updateAdvancedVisibleInputPreloadHints();
  clearTransformProgress();
  hideTransformValueTooltip();
  setTransformStatus("Preview stopped.");
  updateTransformControls();
  scheduleTransformHistogramRefresh();
}

function toggleRasterCalculatorPreview() {
  if (isSelectedAdvancedPreviewActive("raster")) {
    stopSelectedAdvancedPreview("raster");
    return;
  }
  if (transformPreviewEnabled) transformPreviewEnabled.checked = true;
  applyRasterCalculatorPreview();
}

function togglePolarizationPreview() {
  if (isSelectedAdvancedPreviewActive("polarization")) {
    stopSelectedAdvancedPreview("polarization");
    return;
  }
  if (transformPreviewEnabled) transformPreviewEnabled.checked = true;
  applyPolarizationPreview();
}

function getTransformHistogramLayout(height, showColorBar = false) {
  const chromeHeight = Math.min(
    height,
    Math.round(56 * (window.devicePixelRatio || 1)),
  );
  const labelBandHeight = getTransformHistogramLabelBandHeight(chromeHeight);
  const labelTop = height - labelBandHeight;
  const gap = Math.max(1, Math.round(chromeHeight * 0.025));
  const colorBarHeight = showColorBar
    ? Math.max(6, Math.round(chromeHeight * 0.11))
    : 0;
  const colorBarBottom = labelTop - gap;
  const colorBarTop = colorBarBottom - colorBarHeight;
  return {
    labelBandHeight,
    labelTop,
    axisY: labelTop + 0.5,
    colorBarHeight,
    colorBarTop,
    plotHeight: Math.max(
      1,
      showColorBar ? colorBarTop - gap : labelTop - 1,
    ),
  };
}

function drawEmptyTransformHistogram(context, width, height, layout) {
  context.clearRect(0, 0, width, height);
  context.fillStyle = "rgba(255, 255, 255, 0.78)";
  context.fillRect(0, 0, width, height);
  context.strokeStyle = "rgba(17, 17, 17, 0.12)";
  context.beginPath();
  context.moveTo(0, layout.axisY);
  context.lineTo(width, layout.axisY);
  context.stroke();
}

function getTransformHistogramLabelBandHeight(height) {
  return Math.max(14, Math.round(height * 0.3));
}

function shouldDrawTransformHistogramColorBar(transform) {
  if (!isRasterRecipe(transform) && !isPolarizationRecipe(transform)) {
    return false;
  }
  if (!["grayscale", "falseColor"].includes(transform.output)) return false;
  if (!isPolarizationRecipe(transform)) return true;
  return !PetroPolarizationAnalysis.getProductDefinition(
    transform.polarizationProduct,
  )?.categorical;
}

function drawTransformHistogramColorBar(context, width, layout, transform) {
  if (layout.colorBarHeight <= 0 || width <= 0) return;
  for (let x = 0; x < width; x += 1) {
    const normalized = width <= 1 ? 0 : x / (width - 1);
    const rgb = transform.output === "falseColor"
      ? PetroPolarizationAnalysis.getColorMapRgb(
          normalized,
          transform.polarizationColormap,
        )
      : Array(3).fill(Math.round(normalized * 255));
    context.fillStyle = `rgb(${rgb.join(",")})`;
    context.fillRect(x, layout.colorBarTop, 1, layout.colorBarHeight);
  }
  context.strokeStyle = "rgba(17, 17, 17, 0.24)";
  context.lineWidth = 1;
  context.strokeRect(
    0.5,
    layout.colorBarTop + 0.5,
    Math.max(0, width - 1),
    Math.max(0, layout.colorBarHeight - 1),
  );
}

function drawTransformHistogramSeries(context, bins, width, plotHeight, color) {
  const maxCount = Math.max(...bins);
  if (maxCount <= 0) return;
  context.fillStyle = color;
  const barWidth = width / bins.length;
  bins.forEach((count, index) => {
    if (count <= 0) return;
    const barHeight = Math.max(1, (count / maxCount) * (plotHeight - 2));
    context.fillRect(
      index * barWidth,
      plotHeight - barHeight,
      Math.max(1, barWidth),
      barHeight,
    );
  });
}

function drawAnisotropyClassDistribution(context, counts, width, height) {
  const maxCount = Math.max(...counts);
  if (maxCount <= 0) return;
  const gap = Math.max(1, Math.round(width * 0.008));
  const barWidth = (width - gap * (counts.length + 1)) / counts.length;
  counts.forEach((count, code) => {
    const entry = PetroPolarizationAnalysis.ANISOTROPY_CLASSES[code];
    const barHeight = Math.max(1, (count / maxCount) * (height - 6));
    context.fillStyle = `rgb(${entry.color.join(",")})`;
    context.fillRect(
      gap + code * (barWidth + gap),
      height - barHeight - 2,
      Math.max(1, barWidth),
      barHeight,
    );
  });
}

function getTransformHistogramSourceCanvas() {
  return (
    viewer?.drawer?.canvas ||
    viewer?.drawer?.canvases?.[0] ||
    viewer?.canvas?.querySelector?.("canvas") ||
    null
  );
}

function getTransformAnalyticalHistogramDomain(transform) {
  if (isPolarizationRecipe(transform)) {
    const definition = PetroPolarizationAnalysis.getProductDefinition(
      transform.polarizationProduct,
    );
    if (definition?.range?.length === 2) {
      return { min: definition.range[0], max: definition.range[1] };
    }
  }
  if (!isRasterRecipe(transform)) return null;
  if (transform.rasterNormalize || transform.rasterScale === "auto") {
    const selectedTileSet = tileSets()[getSelectedTransformTileSetIndex()];
    const autoScaleRange = derivedPreviewOverlay?.isActiveFor(selectedTileSet)
      ? derivedPreviewOverlay.state?.petroImageAutoScaleRange
      : null;
    if (
      Number.isFinite(autoScaleRange?.min) &&
      Number.isFinite(autoScaleRange?.max) &&
      autoScaleRange.max > autoScaleRange.min
    ) {
      return { min: autoScaleRange.min, max: autoScaleRange.max };
    }
    return {};
  }
  switch (transform.rasterScale) {
    case "custom":
      return {
        min: transform.rasterCustomMin,
        max: transform.rasterCustomMax,
      };
    case "signed":
      return { min: -255, max: 255 };
    case "unit":
      return { min: -1, max: 1 };
    case "raw":
    default:
      return { min: 0, max: 255 };
  }
}

function getTransformVisibleAnalyticalSamples(transform, options = {}) {
  if (!isTransformPreviewEnabled() || !viewer?.viewport || !viewerContainer) {
    return null;
  }
  const tileSet = tileSets()[getSelectedTransformTileSetIndex()];
  const item = derivedPreviewOverlay?.isActiveFor(tileSet)
    ? derivedPreviewOverlay.item
    : null;
  const matrix = item?.tilesMatrix;
  if (!matrix) return null;
  const candidates = [];
  let assessableClassCodes = null;
  const viewportBounds = viewer.viewport.getBounds(true);
  Object.entries(matrix).forEach(([level, columns]) => {
    const numericLevel = Number.parseInt(level, 10);
    if (!Number.isFinite(numericLevel)) return;
    Object.values(columns || {}).forEach((rows) => {
      Object.values(rows || {}).forEach((loadedTile) => {
        const context =
          PetroDerivedPreviewOverlay.getDerivedTileContext2D(loadedTile);
        const values = context?.petroImageAdvancedRawValues;
        const width = context?.petroImageAdvancedRawWidth;
        const height = context?.petroImageAdvancedRawHeight;
        const bounds = getLoadedTileViewportBounds(loadedTile);
        if (
          !values?.length ||
          !bounds ||
          width !== context.canvas?.width ||
          height !== context.canvas?.height
        ) {
          return;
        }
        if (
          bounds.x >= viewportBounds.x + viewportBounds.width ||
          bounds.x + bounds.width <= viewportBounds.x ||
          bounds.y >= viewportBounds.y + viewportBounds.height ||
          bounds.y + bounds.height <= viewportBounds.y
        ) {
          return;
        }
        assessableClassCodes ||=
          context.petroImagePolarizationClassification
            ?.assessableClassCodes || null;
        candidates.push({
          level: numericLevel,
          bounds,
          width,
          height,
          values,
          rgbValues: context.petroImageAdvancedRgbValues || null,
          reliability: context.petroImagePolarizationFitReliability || null,
        });
      });
    });
  });
  if (!candidates.length) return null;
  candidates.sort((a, b) => b.level - a.level);

  const rect = viewerContainer.getBoundingClientRect();
  const screenWidth = Math.max(1, Math.round(rect.width));
  const screenHeight = Math.max(1, Math.round(rect.height));
  const maxSamples = Number.isFinite(options.maxSamples)
    ? Math.max(1, options.maxSamples)
    : 30000;
  const step = Math.max(
    1,
    Math.sqrt((screenWidth * screenHeight) / maxSamples),
  );
  const scalarValues = [];
  const rgbValues = [];
  const reliableValues = [];
  let residualUnchecked = false;
  for (let screenY = step / 2; screenY < screenHeight; screenY += step) {
    for (let screenX = step / 2; screenX < screenWidth; screenX += step) {
      const viewportPoint = viewer.viewport.pointFromPixel(
        new OpenSeadragon.Point(screenX, screenY),
        true,
      );
      let selected = null;
      for (const candidate of candidates) {
        const { bounds } = candidate;
        if (
          viewportPoint.x >= bounds.x &&
          viewportPoint.x < bounds.x + bounds.width &&
          viewportPoint.y >= bounds.y &&
          viewportPoint.y < bounds.y + bounds.height
        ) {
          selected = candidate;
          break;
        }
      }
      if (!selected) continue;
      const xRatio =
        (viewportPoint.x - selected.bounds.x) / selected.bounds.width;
      const yRatio =
        (viewportPoint.y - selected.bounds.y) / selected.bounds.height;
      const pixelX = Math.min(
        selected.width - 1,
        Math.max(0, Math.floor(xRatio * selected.width)),
      );
      const pixelY = Math.min(
        selected.height - 1,
        Math.max(0, Math.floor(yRatio * selected.height)),
      );
      const pixelIndex = pixelY * selected.width + pixelX;
      scalarValues.push(selected.values[pixelIndex]);
      if (selected.rgbValues?.length) {
        const rgbOffset = pixelIndex * 3;
        rgbValues.push(
          selected.rgbValues[rgbOffset],
          selected.rgbValues[rgbOffset + 1],
          selected.rgbValues[rgbOffset + 2],
        );
      }
      reliableValues.push(selected.reliability?.values?.[pixelIndex] === 1);
      residualUnchecked ||= Boolean(selected.reliability?.residualUnchecked);
    }
  }
  if (!scalarValues.length) return null;
  return {
    scalarValues,
    rgbValues,
    reliableValues,
    residualUnchecked,
    assessableClassCodes,
  };
}

function getTransformAnalyticalHistogram(transform) {
  if (!isTransformPreviewEnabled()) return null;
  const rgbMode =
    isPolarizationRecipe(transform) && transform.output === "rgb";
  const samples = getTransformVisibleAnalyticalSamples(transform);
  if (!samples) return null;
  const azimuthConfig = getTransformRoseConfig(transform);
  const filterReliable = Boolean(
    azimuthConfig && transformAzimuthFilter?.value === "reliable",
  );
  let scalarValues = samples.scalarValues;
  let azimuthSummary = null;
  if (azimuthConfig) {
    const filteredValues = [];
    let considered = 0;
    let included = 0;
    samples.scalarValues.forEach((rawValue, index) => {
      const value = Number(rawValue);
      if (!Number.isFinite(value)) return;
      considered += 1;
      if (filterReliable && !samples.reliableValues[index]) return;
      included += 1;
      filteredValues.push(value);
    });
    scalarValues = filteredValues;
    azimuthSummary = {
      config: azimuthConfig,
      considered,
      included,
      residualUnchecked: samples.residualUnchecked,
      filterReliable,
    };
  }
  const valueArrays = [
    rgbMode ? samples.rgbValues : scalarValues,
  ];
  const assessableClassCodes = samples.assessableClassCodes;
  const definition = isPolarizationRecipe(transform)
    ? PetroPolarizationAnalysis.getProductDefinition(
        transform.polarizationProduct,
      )
    : null;
  if (definition?.categorical) {
    const classCounts = new Uint32Array(
      PetroPolarizationAnalysis.ANISOTROPY_CLASSES.length,
    );
    let sampled = 0;
    const totalPixels = valueArrays.reduce(
      (sum, values) => sum + values.length,
      0,
    );
    const stride = Math.max(1, Math.ceil(totalPixels / 75000));
    valueArrays.forEach((values) => {
      for (let index = 0; index < values.length; index += 1) {
        if (sampled % stride === 0) {
          const code = Math.round(values[index]);
          if (code >= 0 && code < classCounts.length) classCounts[code] += 1;
        }
        sampled += 1;
      }
    });
    return {
      classCounts,
      assessableClassCodes,
      min: 0,
      max: classCounts.length - 1,
    };
  }
  if (rgbMode) {
    const rgbBins = [
      new Uint32Array(256),
      new Uint32Array(256),
      new Uint32Array(256),
    ];
    const totalPixels = valueArrays.reduce(
      (sum, values) => sum + Math.floor(values.length / 3),
      0,
    );
    const stride = Math.max(1, Math.ceil(totalPixels / 75000));
    let pixelIndex = 0;
    valueArrays.forEach((values) => {
      for (let offset = 0; offset < values.length; offset += 3) {
        if (pixelIndex % stride === 0) {
          for (let channelIndex = 0; channelIndex < 3; channelIndex += 1) {
            const value = values[offset + channelIndex];
            if (Number.isFinite(value)) {
              rgbBins[channelIndex][clampColorValue(value)] += 1;
            }
          }
        }
        pixelIndex += 1;
      }
    });
    return { rgbBins, min: 0, max: 255 };
  }
  const domain = getTransformAnalyticalHistogramDomain(transform) || {};
  const histogram = PetroDerivedPreviewOverlay.buildScalarHistogram(valueArrays, {
    ...domain,
    binCount: 256,
    maxSamples: 75000,
  });
  if (histogram) return { ...histogram, azimuthSummary };
  if (!azimuthSummary) return null;
  return {
    bins: new Uint32Array(256),
    min: Number.isFinite(domain.min) ? domain.min : 0,
    max: Number.isFinite(domain.max) ? domain.max : 1,
    azimuthSummary,
  };
}

function formatTransformAzimuthSummary(summary) {
  if (!summary) return "";
  const percent = summary.considered > 0
    ? Math.round((summary.included / summary.considered) * 100)
    : 0;
  const filterLabel = summary.filterReliable
    ? `${percent}% reliable included`
    : "All fitted azimuths included";
  const residualNote = summary.residualUnchecked
    ? " · residual unchecked"
    : "";
  const maskNote = summary.filterReliable
    ? " · grey = unreliable"
    : "";
  return (
    `${filterLabel} · ${summary.included.toLocaleString()} pixels sampled${residualNote}\n` +
    `${summary.config.modality} · ${summary.config.symmetryLabel}${maskNote}`
  );
}

function updateTransformHistogramStatus(transform, summary = null) {
  if (!transformHistogramStatus) return;
  const config = getTransformRoseConfig(transform);
  const visible = Boolean(config && transformPlotView === "histogram");
  transformHistogramStatus.hidden = !visible;
  if (!visible) return;
  if (!derivedPreviewOverlay?.state) {
    transformHistogramStatus.textContent =
      "Start an azimuth preview to display its histogram.";
    return;
  }
  transformHistogramStatus.textContent = summary
    ? formatTransformAzimuthSummary(summary)
    : "Waiting for visible azimuth tiles…";
}

function getTransformHistogramAxisLabels(range = null) {
  if (range && Number.isFinite(range.min) && Number.isFinite(range.max)) {
    return [range.min, range.max].map(formatTransformTooltipNumber);
  }
  const transform = getTransformOptionsFromControls();
  if (isPolarizationRecipe(transform)) {
    const definition = PetroPolarizationAnalysis.getProductDefinition(
      transform.polarizationProduct,
    );
    if (definition?.range) {
      return definition.range.map(formatTransformTooltipNumber);
    }
  }
  if (isRasterRecipe(transform) && !transform.rasterNormalize) {
    switch (transform.rasterScale) {
      case "custom":
        return [
          formatTransformTooltipNumber(transform.rasterCustomMin),
          formatTransformTooltipNumber(transform.rasterCustomMax),
        ];
      case "signed":
        return ["-255", "255"];
      case "unit":
        return ["-1", "1"];
      case "raw":
        return ["0", "255"];
      default:
        break;
    }
  }
  return ["0", "255"];
}

function drawTransformHistogramAxisLabels(context, width, height, range = null) {
  const [minLabel, maxLabel] = getTransformHistogramAxisLabels(range);
  context.save();
  context.fillStyle = "rgba(17, 17, 17, 0.68)";
  const chromeHeight = Math.min(
    height,
    Math.round(56 * (window.devicePixelRatio || 1)),
  );
  context.font = `${Math.max(9, Math.round(chromeHeight * 0.22))}px system-ui, sans-serif`;
  context.textBaseline = "bottom";
  context.textAlign = "left";
  context.fillText(minLabel, 3, height - 2);
  context.textAlign = "right";
  context.fillText(maxLabel, width - 3, height - 2);
  context.restore();
}

function renderTransformHistogram() {
  if (!transformHistogramCanvas) return;
  const canvas = transformHistogramCanvas;
  const rect = canvas.getBoundingClientRect();
  const cssWidth = Math.max(
    1,
    Math.round(rect.width || canvas.clientWidth || 1),
  );
  const cssHeight = Math.max(1, Math.round(rect.height || 36));
  const scale = window.devicePixelRatio || 1;
  const width = Math.max(1, Math.round(cssWidth * scale));
  const height = Math.max(1, Math.round(cssHeight * scale));
  if (canvas.width !== width || canvas.height !== height) {
    canvas.width = width;
    canvas.height = height;
  }

  const context = canvas.getContext("2d", { willReadFrequently: true });
  if (!context) return;
  const transform = getTransformOptionsFromControls();
  updateTransformHistogramStatus(transform);
  const showColorBar = shouldDrawTransformHistogramColorBar(transform);
  const layout = getTransformHistogramLayout(height, showColorBar);
  drawEmptyTransformHistogram(context, width, height, layout);
  if (showColorBar) {
    drawTransformHistogramColorBar(context, width, layout, transform);
  }

  if (!transformImageryPalette || transformImageryPalette.hidden) {
    drawTransformHistogramAxisLabels(context, width, height);
    return;
  }
  const analyticalHistogram = getTransformAnalyticalHistogram(transform);
  if (analyticalHistogram) {
    updateTransformHistogramStatus(
      transform,
      analyticalHistogram.azimuthSummary,
    );
    if (analyticalHistogram.classCounts) {
      drawAnisotropyClassDistribution(
        context,
        analyticalHistogram.classCounts,
        width,
        height,
      );
      updatePolarizationClassLegendCounts(
        analyticalHistogram.classCounts,
        analyticalHistogram.assessableClassCodes,
      );
      return;
    } else if (analyticalHistogram.rgbBins) {
      [
        "rgba(220, 50, 47, 0.42)",
        "rgba(30, 160, 80, 0.42)",
        "rgba(38, 95, 220, 0.42)",
      ].forEach((color, channelIndex) => {
        drawTransformHistogramSeries(
          context,
          analyticalHistogram.rgbBins[channelIndex],
          width,
          layout.plotHeight,
          color,
        );
      });
    } else {
      drawTransformHistogramSeries(
        context,
        analyticalHistogram.bins,
        width,
        layout.plotHeight,
        "rgba(17, 17, 17, 0.82)",
      );
    }
    drawTransformHistogramAxisLabels(context, width, height, {
      min: analyticalHistogram.min,
      max: analyticalHistogram.max,
    });
    return;
  }
  const selectedTileSet = tileSets()[getSelectedTransformTileSetIndex()];
  const categoricalHistogram = Boolean(
    isPolarizationRecipe(transform) &&
      PetroPolarizationAnalysis.getProductDefinition(
        transform.polarizationProduct,
      )?.categorical,
  );
  if (categoricalHistogram) updatePolarizationClassLegendCounts();
  const analyticalPreviewPending =
    isTransformPreviewEnabled() &&
    (isRasterRecipe(transform) || isPolarizationRecipe(transform)) &&
    derivedPreviewOverlay?.isActiveFor(selectedTileSet);
  if (analyticalPreviewPending) {
    if (!categoricalHistogram) {
      drawTransformHistogramAxisLabels(context, width, height);
    }
    return;
  }
  if (categoricalHistogram) return;
  const sourceCanvas = getTransformHistogramSourceCanvas();
  if (!sourceCanvas?.width || !sourceCanvas?.height) {
    drawTransformHistogramAxisLabels(context, width, height);
    return;
  }

  const outputRequestsRgb = transform.output === "rgb";
  const forceScalarHistogram =
    transform.output === "falseColor" ||
    (transform.output === "grayscale" &&
      (isRasterRecipe(transform) || isPolarizationRecipe(transform)));
  const rgbBins = [
    new Uint32Array(256),
    new Uint32Array(256),
    new Uint32Array(256),
  ];
  const grayBins = new Uint32Array(256);
  let sampledPixels = 0;
  let hasColorSamples = false;

  const sampleCanvas = document.createElement("canvas");
  sampleCanvas.width = 192;
  sampleCanvas.height = Math.max(
    36,
    Math.round(192 * (height / Math.max(width, 1))),
  );
  const sampleContext = sampleCanvas.getContext("2d", {
    willReadFrequently: true,
  });
  if (!sampleContext) {
    drawTransformHistogramAxisLabels(context, width, height);
    return;
  }
  sampleContext.drawImage(
    sourceCanvas,
    0,
    0,
    sourceCanvas.width,
    sourceCanvas.height,
    0,
    0,
    sampleCanvas.width,
    sampleCanvas.height,
  );

  let imageData = null;
  try {
    imageData = sampleContext.getImageData(
      0,
      0,
      sampleCanvas.width,
      sampleCanvas.height,
    );
  } catch (error) {
    drawTransformHistogramAxisLabels(context, width, height);
    return;
  }

  const data = imageData.data;
  for (let offset = 0; offset < data.length; offset += 4) {
    if (data[offset + 3] === 0) continue;
    const red = data[offset];
    const green = data[offset + 1];
    const blue = data[offset + 2];
    rgbBins[0][red] += 1;
    rgbBins[1][green] += 1;
    rgbBins[2][blue] += 1;
    grayBins[Math.round((red + green + blue) / 3)] += 1;
    if (red !== green || green !== blue) {
      hasColorSamples = true;
    }
    sampledPixels += 1;
  }

  if (sampledPixels === 0) {
    drawTransformHistogramAxisLabels(context, width, height);
    return;
  }
  const drawRgb =
    !forceScalarHistogram && (outputRequestsRgb || hasColorSamples);
  if (drawRgb) {
    drawTransformHistogramSeries(
      context,
      rgbBins[0],
      width,
      layout.plotHeight,
      "rgba(220, 50, 47, 0.42)",
    );
    drawTransformHistogramSeries(
      context,
      rgbBins[1],
      width,
      layout.plotHeight,
      "rgba(30, 160, 80, 0.42)",
    );
    drawTransformHistogramSeries(
      context,
      rgbBins[2],
      width,
      layout.plotHeight,
      "rgba(38, 95, 220, 0.42)",
    );
  } else {
    drawTransformHistogramSeries(
      context,
      grayBins,
      width,
      layout.plotHeight,
      "rgba(17, 17, 17, 0.82)",
    );
  }
  drawTransformHistogramAxisLabels(context, width, height);
}

function scheduleTransformHistogramRefresh(options = {}) {
  const delay = Number.isFinite(options.delay) ? Math.max(0, options.delay) : 0;
  if (delay > 0) {
    if (transformHistogramRefreshTimer !== null) {
      window.clearTimeout(transformHistogramRefreshTimer);
    }
    transformHistogramRefreshTimer = window.setTimeout(() => {
      transformHistogramRefreshTimer = null;
      scheduleTransformHistogramRefresh();
    }, delay);
    return;
  }
  if (transformHistogramRefreshHandle !== null) return;
  const schedule =
    typeof window.requestAnimationFrame === "function"
      ? window.requestAnimationFrame.bind(window)
      : (callback) => window.setTimeout(callback, 16);
  transformHistogramRefreshHandle = schedule(() => {
    transformHistogramRefreshHandle = null;
    if (transformPlotView === "rose") renderTransformRoseInspector();
    else renderTransformHistogram();
  });
}

function getTransformRoseConfig(transform = null) {
  const settings = transform || getTransformOptionsFromControls();
  switch (settings.polarizationProduct) {
    case "ppl_azimuth":
      return {
        modality: "PPL",
        nativePeriod: 180,
        binWidth: 10,
        repetitions: 2,
        symmetryLabel: "180° axial",
      };
    case "xpl_extinction_azimuth":
      return {
        modality: "XPL",
        nativePeriod: 90,
        binWidth: 5,
        repetitions: 4,
        symmetryLabel: "90° extinction-equivalent",
      };
    default:
      return null;
  }
}

function shouldMaskUnreliableAzimuthPreview(transform = null) {
  const settings = transform || getTransformOptionsFromControls();
  return Boolean(
    getTransformRoseConfig(settings) &&
      transformAzimuthFilter?.value === "reliable",
  );
}

function updatePolarizationAzimuthPreviewMask() {
  const tileSet = tileSets()[getSelectedTransformTileSetIndex()];
  const transform = getTileSetTransform(tileSet);
  if (
    !tileSet ||
    !isPolarizationRecipe(transform) ||
    !getTransformRoseConfig(transform) ||
    !derivedPreviewOverlay?.isActiveFor(tileSet)
  ) {
    return;
  }
  const definition = PetroPolarizationAnalysis.getProductDefinition(
    transform.polarizationProduct,
  );
  const appearance = getTileSetAppearance(tileSet);
  const matrix = derivedPreviewOverlay.item?.tilesMatrix;
  Object.values(matrix || {}).forEach((columns) => {
    Object.values(columns || {}).forEach((rows) => {
      Object.values(rows || {}).forEach((loadedTile) => {
        const context =
          PetroDerivedPreviewOverlay.getDerivedTileContext2D(loadedTile);
        const values = context?.petroImageAdvancedRawValues;
        const reliability = context?.petroImagePolarizationFitReliability;
        if (
          !context?.canvas ||
          !values?.length ||
          !reliability?.values?.length ||
          context.petroImageAdvancedRawWidth !== context.canvas.width ||
          context.petroImageAdvancedRawHeight !== context.canvas.height
        ) {
          return;
        }
        mapPolarizationRasterToImageData(
          context,
          {
            values,
            rgbValues: context.petroImageAdvancedRgbValues || null,
            definition,
            fitReliability: reliability,
          },
          transform,
          {
            maskUnreliable: shouldMaskUnreliableAzimuthPreview(transform),
          },
        );
        if (!isDefaultAppearanceValue(appearance)) {
          applyTileSetAppearanceToContext(context, appearance);
        }
        markContextAsOpaqueTileContext(context);
      });
    });
  });
  viewer?.forceRedraw?.();
  refreshTransformValueTooltipAtLastPointer();
}

function getTransformRoseData(transform = null) {
  const settings = transform || getTransformOptionsFromControls();
  const config = getTransformRoseConfig(settings);
  if (!config || !isTransformPreviewEnabled()) return null;
  const samples = getTransformVisibleAnalyticalSamples(settings);
  if (!samples) return null;

  const filterReliable = transformAzimuthFilter?.value === "reliable";
  const fullBinCount = Math.round(360 / config.binWidth);
  const bins = new Uint32Array(fullBinCount);
  let considered = 0;
  let included = 0;
  samples.scalarValues.forEach((rawValue, index) => {
    const value = Number(rawValue);
    if (!Number.isFinite(value)) return;
    considered += 1;
    if (filterReliable && !samples.reliableValues[index]) return;
    included += 1;
    const nativeAngle = PetroPolarizationAnalysis.positiveModulo(
      value,
      config.nativePeriod,
    );
    for (
      let repetition = 0;
      repetition < config.repetitions;
      repetition += 1
    ) {
      const angle = nativeAngle + repetition * config.nativePeriod;
      const bin = Math.min(
        fullBinCount - 1,
        Math.floor(angle / config.binWidth),
      );
      bins[bin] += 1;
    }
  });
  return {
    bins,
    config,
    considered,
    included,
    residualUnchecked: samples.residualUnchecked,
    filterReliable,
  };
}

function drawTransformRoseChart(data) {
  if (!transformRoseCanvas) return;
  const canvas = transformRoseCanvas;
  const rect = canvas.getBoundingClientRect();
  const cssWidth = Math.max(1, Math.round(rect.width || canvas.clientWidth || 1));
  const cssHeight = Math.max(1, Math.round(rect.height || 128));
  const scale = window.devicePixelRatio || 1;
  canvas.width = Math.max(1, Math.round(cssWidth * scale));
  canvas.height = Math.max(1, Math.round(cssHeight * scale));
  const context = canvas.getContext("2d");
  if (!context) return;
  context.setTransform(scale, 0, 0, scale, 0, 0);
  context.clearRect(0, 0, cssWidth, cssHeight);
  context.fillStyle = "rgba(255,255,255,0.86)";
  context.fillRect(0, 0, cssWidth, cssHeight);
  const centerX = cssWidth / 2;
  const centerY = cssHeight / 2;
  const radius = Math.max(8, Math.min(cssWidth, cssHeight) / 2 - 15);
  context.strokeStyle = "rgba(17,17,17,0.16)";
  context.lineWidth = 1;
  [0.5, 1].forEach((fraction) => {
    context.beginPath();
    context.arc(centerX, centerY, radius * fraction, 0, Math.PI * 2);
    context.stroke();
  });
  context.beginPath();
  context.moveTo(centerX - radius, centerY);
  context.lineTo(centerX + radius, centerY);
  context.moveTo(centerX, centerY - radius);
  context.lineTo(centerX, centerY + radius);
  context.stroke();

  const maxCount = data?.bins?.length ? Math.max(...data.bins) : 0;
  if (maxCount > 0) {
    const binAngle = (Math.PI * 2) / data.bins.length;
    data.bins.forEach((count, index) => {
      if (!count) return;
      const wedgeRadius = radius * (count / maxCount);
      const start = index * binAngle - Math.PI / 2;
      const end = start + binAngle;
      context.beginPath();
      context.moveTo(centerX, centerY);
      context.arc(centerX, centerY, wedgeRadius, start, end);
      context.closePath();
      context.fillStyle = "rgba(39,133,74,0.72)";
      context.fill();
    });
  }

  context.fillStyle = "rgba(17,17,17,0.68)";
  context.font = "8px system-ui, sans-serif";
  context.textBaseline = "bottom";
  context.textAlign = "center";
  context.fillText("0°", centerX, centerY - radius - 2);
  context.textBaseline = "middle";
  context.textAlign = "left";
  context.fillText("90°", centerX + radius + 3, centerY);
  context.textBaseline = "top";
  context.textAlign = "center";
  context.fillText("180°", centerX, centerY + radius + 2);
  context.textBaseline = "middle";
  context.textAlign = "right";
  context.fillText("270°", centerX - radius - 3, centerY);
}

function renderTransformRoseInspector() {
  if (transformPlotView !== "rose") return;
  const transform = getTransformOptionsFromControls();
  const data = getTransformRoseData(transform);
  drawTransformRoseChart(data);
  if (!transformRoseStatus) return;
  if (!derivedPreviewOverlay?.state) {
    transformRoseStatus.textContent =
      "Start an azimuth preview to display its rose diagram.";
    return;
  }
  if (!data) {
    transformRoseStatus.textContent = "Waiting for visible azimuth tiles…";
    return;
  }
  transformRoseStatus.textContent = formatTransformAzimuthSummary(data);
}

function getTransformFitAvailableModalities(transform = null) {
  const settings = transform || getTransformOptionsFromControls();
  if (!isPolarizationRecipe(settings)) return [];
  const required = getPolarizationRequiredModalities(
    settings.polarizationProduct,
    settings,
  );
  return ["ppl", "xpl"].filter((modality) =>
    required.includes(modality) &&
    Boolean(
      getPolarizationFitModel(
        modality,
        getPolarizationTileSet(modality, settings),
      ),
    ),
  );
}

function getPreferredTransformFitModality(transform, available) {
  const definition = PetroPolarizationAnalysis.getProductDefinition(
    transform?.polarizationProduct,
  );
  if (definition?.mode === "xpl" && available.includes("xpl")) return "xpl";
  if (definition?.mode === "ppl" && available.includes("ppl")) return "ppl";
  return available[0] || "ppl";
}

function syncTransformFitControls(transform = null) {
  const settings = transform || getTransformOptionsFromControls();
  const available = getTransformFitAvailableModalities(settings);
  const fitAvailable = available.length > 0;
  const selectedTileSet = tileSets()[getSelectedTransformTileSetIndex()];
  const fitPreviewAvailable = Boolean(
    fitAvailable &&
      isPolarizationRecipe(settings) &&
      isTransformPreviewEnabled() &&
      isTransformSourceTileSetVisible() &&
      derivedPreviewOverlay?.isActiveFor(selectedTileSet),
  );
  const roseAvailable = Boolean(getTransformRoseConfig(settings));
  if (transformFitViewButton) {
    transformFitViewButton.disabled = !fitPreviewAvailable;
    transformFitViewButton.title = fitPreviewAvailable
      ? "Inspect the polarization fit under the cursor"
      : "Start and show a polarization preview to inspect fits";
  }
  if (transformRoseViewButton) transformRoseViewButton.disabled = !roseAvailable;
  if (!fitPreviewAvailable && transformPlotView === "fit") {
    transformPlotView = "histogram";
    transformFitPinnedPoint = null;
    transformFitSample = null;
    clearTransformFitPinMarker();
  }
  if (!roseAvailable && transformPlotView === "rose") {
    transformPlotView = "histogram";
  }
  if (transformFitModality) {
    Array.from(transformFitModality.options).forEach((option) => {
      option.disabled = !available.includes(option.value);
    });
    if (!available.includes(transformFitModality.value)) {
      transformFitModality.value = getPreferredTransformFitModality(
        settings,
        available,
      );
    }
    transformFitModality.disabled = !fitAvailable;
  }
  const showingFit = transformPlotView === "fit" && fitPreviewAvailable;
  const showingRose = transformPlotView === "rose" && roseAvailable;
  if (transformAzimuthFilterControls) {
    transformAzimuthFilterControls.hidden = !roseAvailable || showingFit;
  }
  transformHistogramViewButton?.setAttribute(
    "aria-pressed",
    showingFit || showingRose ? "false" : "true",
  );
  transformFitViewButton?.setAttribute(
    "aria-pressed",
    showingFit ? "true" : "false",
  );
  transformRoseViewButton?.setAttribute(
    "aria-pressed",
    showingRose ? "true" : "false",
  );
  if (transformHistogramCanvas) {
    transformHistogramCanvas.hidden = showingFit || showingRose;
  }
  if (transformHistogramStatus) {
    transformHistogramStatus.hidden = showingFit || showingRose || !roseAvailable;
  }
  if (transformFitInspector) transformFitInspector.hidden = !showingFit;
  if (transformRoseInspector) transformRoseInspector.hidden = !showingRose;
  if (transformPolarizationClassLegend) {
    const definition = PetroPolarizationAnalysis.getProductDefinition(
      settings.polarizationProduct,
    );
    transformPolarizationClassLegend.hidden =
      showingFit ||
      showingRose ||
      !isPolarizationRecipe(settings) ||
      !definition?.categorical;
  }
  if (showingFit) scheduleTransformFitRefresh();
  if (showingRose) scheduleTransformHistogramRefresh();
}

function setTransformPlotView(view) {
  transformPlotView = ["fit", "rose"].includes(view) ? view : "histogram";
  const transform = getTransformOptionsFromControls();
  if (transformPlotView === "fit" && transformFitModality) {
    transformFitSample = null;
    const available = getTransformFitAvailableModalities(transform);
    const preferred = getPreferredTransformFitModality(transform, available);
    if (available.includes(preferred)) transformFitModality.value = preferred;
  } else {
    transformFitPinnedPoint = null;
    clearTransformFitPinMarker();
  }
  syncTransformFitControls(transform);
  scheduleTransformHistogramRefresh();
  scheduleClampOpenToolPalettes();
}

function getTransformFitLoadedTile(viewportPoint) {
  const item = derivedPreviewOverlay?.item;
  if (!item?.tilesMatrix || !viewportPoint) return null;
  let best = null;
  Object.entries(item.tilesMatrix).forEach(([level, columns]) => {
    Object.entries(columns || {}).forEach(([x, rows]) => {
      Object.entries(rows || {}).forEach(([y, loadedTile]) => {
        const context =
          PetroDerivedPreviewOverlay.getDerivedTileContext2D(loadedTile);
        if (!context?.canvas) return;
        const bounds = getLoadedTileViewportBounds(loadedTile);
        if (!bounds) return;
        const xRatio = (viewportPoint.x - bounds.x) / bounds.width;
        const yRatio = (viewportPoint.y - bounds.y) / bounds.height;
        if (xRatio < 0 || xRatio >= 1 || yRatio < 0 || yRatio >= 1) return;
        const numericLevel = Number.parseInt(level, 10);
        if (!best || numericLevel > best.level) {
          best = {
            level: numericLevel,
            x: Number.parseInt(x, 10),
            y: Number.parseInt(y, 10),
            xRatio,
            yRatio,
          };
        }
      });
    });
  });
  return best;
}

function sampleTransformFitSourceImage(data, xRatio, yRatio, channel) {
  const width = Number(data?.naturalWidth || data?.videoWidth || data?.width);
  const height = Number(data?.naturalHeight || data?.videoHeight || data?.height);
  if (!width || !height) return Number.NaN;
  if (!transformFitScratchCanvas) {
    transformFitScratchCanvas = document.createElement("canvas");
    transformFitScratchCanvas.width = 1;
    transformFitScratchCanvas.height = 1;
  }
  const context = transformFitScratchCanvas.getContext("2d", {
    willReadFrequently: true,
  });
  if (!context) return Number.NaN;
  const x = Math.min(width - 1, Math.max(0, Math.floor(xRatio * width)));
  const y = Math.min(height - 1, Math.max(0, Math.floor(yRatio * height)));
  try {
    context.clearRect(0, 0, 1, 1);
    context.drawImage(data, x, y, 1, 1, 0, 0, 1, 1);
    const pixel = context.getImageData(0, 0, 1, 1).data;
    if (channel === "red") return pixel[0];
    if (channel === "green") return pixel[1];
    if (channel === "blue") return pixel[2];
    return 0.2126 * pixel[0] + 0.7152 * pixel[1] + 0.0722 * pixel[2];
  } catch (error) {
    return Number.NaN;
  }
}

async function calculateTransformFitSample(point, requestGeneration) {
  const state = derivedPreviewOverlay?.state;
  const transform = getTransformOptionsFromControls();
  const selectedTileSet = tileSets()[getSelectedTransformTileSetIndex()];
  if (
    !point ||
    !state?.item ||
    !state.petroImageSourceCache ||
    !state.petroImageReferenceTile?.image ||
    !derivedPreviewOverlay.isActiveFor(selectedTileSet) ||
    !isTransformPreviewEnabled() ||
    !isPolarizationRecipe(transform)
  ) {
    return null;
  }
  const modality = transformFitModality?.value || "ppl";
  const sourceTileSet = getPolarizationTileSet(modality, transform);
  const model = getPolarizationFitModel(modality, sourceTileSet);
  const loadedTile = getTransformFitLoadedTile(point.viewportPoint);
  if (!model || !loadedTile) return null;
  const referenceSource = state.petroImageReferenceTile.image.source;
  const referenceBounds = referenceSource?.getTileBounds?.(
    loadedTile.level,
    loadedTile.x,
    loadedTile.y,
  );
  const referencePoint = referenceBounds
    ? {
        x: referenceBounds.x + loadedTile.xRatio * referenceBounds.width,
        y: referenceBounds.y + loadedTile.yRatio * referenceBounds.height,
      }
    : null;
  let waiting = false;
  const values = await Promise.all(
    (sourceTileSet.tiles || []).map(async (tile) => {
      const coordinates = getMappedDerivedSourceCoordinates(
        state.petroImageReferenceTile.image,
        tile.image,
        loadedTile.level,
        loadedTile.x,
        loadedTile.y,
      );
      const promise = state.petroImageSourceCache.get(
        getDerivedSourceCacheKey(tile, coordinates),
      );
      if (!promise) {
        waiting = true;
        return Number.NaN;
      }
      const data = await promise.catch(() => null);
      const sourceBounds = tile.image?.source?.getTileBounds?.(
        coordinates.level,
        coordinates.x,
        coordinates.y,
      );
      const xRatio = referencePoint && sourceBounds
        ? (referencePoint.x - sourceBounds.x) / sourceBounds.width
        : loadedTile.xRatio;
      const yRatio = referencePoint && sourceBounds
        ? (referencePoint.y - sourceBounds.y) / sourceBounds.height
        : loadedTile.yRatio;
      return sampleTransformFitSourceImage(
        data,
        xRatio,
        yRatio,
        transform.channel,
      );
    }),
  );
  if (requestGeneration !== transformFitRequestGeneration) return null;
  if (waiting || values.some((value) => !Number.isFinite(value))) {
    return { waiting: true, modality, point };
  }
  const fit = PetroPolarizationAnalysis.fitHarmonicValues(model, values);
  if (!fit) return null;
  return {
    modality,
    point,
    angles: model.angles,
    values,
    model,
    fit,
  };
}

function drawTransformFitChart(sample) {
  if (!transformFitCanvas) return;
  const canvas = transformFitCanvas;
  const rect = canvas.getBoundingClientRect();
  const cssWidth = Math.max(1, Math.round(rect.width || canvas.clientWidth || 1));
  const cssHeight = Math.max(1, Math.round(rect.height || 94));
  const scale = window.devicePixelRatio || 1;
  canvas.width = Math.max(1, Math.round(cssWidth * scale));
  canvas.height = Math.max(1, Math.round(cssHeight * scale));
  const context = canvas.getContext("2d");
  if (!context) return;
  context.setTransform(scale, 0, 0, scale, 0, 0);
  context.clearRect(0, 0, cssWidth, cssHeight);
  context.fillStyle = "rgba(255,255,255,0.86)";
  context.fillRect(0, 0, cssWidth, cssHeight);
  if (!sample?.fit) return;
  const left = 31;
  const right = 5;
  const top = 6;
  const bottom = 16;
  const plotWidth = Math.max(1, cssWidth - left - right);
  const plotHeight = Math.max(1, cssHeight - top - bottom);
  const period = 360 / sample.model.harmonic;
  const curveValues = Array.from({ length: 73 }, (_, index) => {
    const angle = (index / 72) * period;
    return {
      angle,
      value: PetroPolarizationAnalysis.evaluateHarmonicFitAtAngle(
        sample.model,
        sample.fit,
        angle,
      ),
    };
  });
  const allValues = [
    ...sample.values,
    ...curveValues.map((entry) => entry.value),
  ];
  let minValue = Math.min(...allValues);
  let maxValue = Math.max(...allValues);
  const padding = Math.max(2, (maxValue - minValue) * 0.12);
  minValue = Math.max(0, minValue - padding);
  maxValue = Math.min(255, maxValue + padding);
  if (maxValue <= minValue) maxValue = minValue + 1;
  const xFor = (angle) =>
    left +
    (PetroPolarizationAnalysis.positiveModulo(angle, period) / period) *
      plotWidth;
  const yFor = (value) =>
    top + ((maxValue - value) / (maxValue - minValue)) * plotHeight;
  context.strokeStyle = "rgba(17,17,17,0.14)";
  context.lineWidth = 1;
  [0, 0.5, 1].forEach((fraction) => {
    const y = top + fraction * plotHeight;
    context.beginPath();
    context.moveTo(left, y);
    context.lineTo(left + plotWidth, y);
    context.stroke();
  });
  context.strokeStyle = "#27854a";
  context.lineWidth = 1.5;
  context.beginPath();
  curveValues.forEach((entry, index) => {
    const x = left + (entry.angle / period) * plotWidth;
    const y = yFor(entry.value);
    if (index === 0) context.moveTo(x, y);
    else context.lineTo(x, y);
  });
  context.stroke();
  context.fillStyle = "#17202a";
  sample.angles.forEach((angle, index) => {
    context.beginPath();
    context.arc(xFor(angle), yFor(sample.values[index]), 2.5, 0, Math.PI * 2);
    context.fill();
  });
  context.fillStyle = "rgba(17,17,17,0.68)";
  context.font = "8px system-ui, sans-serif";
  context.textBaseline = "middle";
  context.textAlign = "right";
  context.fillText(maxValue.toFixed(1), left - 3, top + 2);
  context.fillText(
    minValue.toFixed(1),
    left - 3,
    top + plotHeight - 2,
  );
  context.textBaseline = "bottom";
  context.textAlign = "left";
  context.fillText("0°", left, cssHeight - 2);
  context.textAlign = "right";
  context.fillText(`${period}°`, left + plotWidth, cssHeight - 2);
}

function renderTransformFitInspector() {
  if (transformPlotView !== "fit") return;
  drawTransformFitChart(transformFitSample);
  if (!transformFitStatus) return;
  if (transformFitSample?.waiting) {
    transformFitStatus.textContent = "Waiting for source stack tiles…";
  } else if (!transformFitSample?.fit) {
    transformFitStatus.textContent = derivedPreviewOverlay?.state
      ? "Move over a loaded preview tile to inspect a fit. Double-click to pin."
      : "Start a polarization preview, then move over the image.";
  } else {
    const { modality, fit } = transformFitSample;
    const normalizedRmse = fit.rmse / Math.max(Math.abs(fit.mean), fit.amplitude, 1);
    const maxFitError = getPolarizationClassificationThresholds().maxFitError;
    const quality = fit.residualDegreesOfFreedom > 0
      ? normalizedRmse <= maxFitError
        ? "reliable"
        : "uncertain"
      : "exact fit; residual unchecked";
    const azimuth = modality === "xpl" ? fit.minimumAzimuth : fit.maximumAzimuth;
    transformFitStatus.textContent =
      `RMSE ${formatTransformTooltipNumber(fit.rmse)} DN · nRMSE ${formatTransformTooltipNumber(normalizedRmse)} · ${quality}\n` +
      `Min ${formatTransformTooltipNumber(fit.minimum)} · Max ${formatTransformTooltipNumber(fit.maximum)} · Mod ${formatTransformTooltipNumber(fit.amplitude)} · Norm ${formatTransformTooltipNumber(fit.normalizedModulation)} · Az ${formatTransformTooltipNumber(azimuth)}°`;
  }
  if (transformFitPinButton) {
    transformFitPinButton.disabled = !transformFitPinnedPoint && !transformFitLastHoverPoint;
    transformFitPinButton.textContent = transformFitPinnedPoint
      ? "Unpin"
      : "Pin point";
    transformFitPinButton.setAttribute(
      "aria-pressed",
      transformFitPinnedPoint ? "true" : "false",
    );
  }
}

function scheduleTransformFitRefresh() {
  if (transformPlotView !== "fit" || transformFitRefreshHandle !== null) return;
  transformFitRefreshHandle = window.requestAnimationFrame(async () => {
    transformFitRefreshHandle = null;
    const point = transformFitPinnedPoint || transformFitLastHoverPoint;
    const requestGeneration = ++transformFitRequestGeneration;
    transformFitSample = await calculateTransformFitSample(
      point,
      requestGeneration,
    );
    if (requestGeneration !== transformFitRequestGeneration) return;
    renderTransformFitInspector();
  });
}

function clearTransformFitPinMarker() {
  if (!transformFitPinMarker) return;
  viewer?.removeOverlay?.(transformFitPinMarker);
  transformFitPinMarker = null;
}

function updateTransformFitPinMarker() {
  clearTransformFitPinMarker();
  if (!transformFitPinnedPoint?.viewportPoint) return;
  const marker = document.createElement("div");
  marker.className = "transform-fit-pin-marker";
  marker.setAttribute("aria-hidden", "true");
  viewer.addOverlay({
    element: marker,
    location: transformFitPinnedPoint.viewportPoint,
    placement: OpenSeadragon.Placement.CENTER,
    checkResize: false,
  });
  transformFitPinMarker = marker;
}

function toggleTransformFitPin() {
  if (transformFitPinnedPoint) {
    transformFitPinnedPoint = null;
    clearTransformFitPinMarker();
  } else if (transformFitLastHoverPoint) {
    transformFitPinnedPoint = {
      viewportPoint: new OpenSeadragon.Point(
        transformFitLastHoverPoint.viewportPoint.x,
        transformFitLastHoverPoint.viewportPoint.y,
      ),
    };
    updateTransformFitPinMarker();
  }
  scheduleTransformFitRefresh();
  renderTransformFitInspector();
}

function clearTransformFitInspector(options = {}) {
  transformFitRequestGeneration += 1;
  transformFitSample = null;
  transformFitPinnedPoint = null;
  if (options.clearHover) transformFitLastHoverPoint = null;
  clearTransformFitPinMarker();
  renderTransformFitInspector();
}

function updateTransformFitHoverPoint(event) {
  if (
    transformPlotView !== "fit" ||
    transformFitPinnedPoint ||
    !isPolarizationRecipe(getTransformOptionsFromControls()) ||
    isTransformValueTooltipSuppressedAtEvent(event) ||
    !viewer?.viewport
  ) {
    return;
  }
  const point = getTransformFitPointFromEvent(event);
  if (!point) return;
  transformFitLastHoverPoint = point;
  scheduleTransformFitRefresh();
}

function getTransformFitPointFromEvent(event) {
  if (!viewer?.viewport || !viewerContainer) return null;
  const rect = viewerContainer.getBoundingClientRect();
  const elementPoint = new OpenSeadragon.Point(
    event.clientX - rect.left,
    event.clientY - rect.top,
  );
  const viewportPoint = viewer.viewport.pointFromPixel(elementPoint, true);
  return getTransformFitLoadedTile(viewportPoint)
    ? { viewportPoint }
    : null;
}

function pinTransformFitPointAtEvent(event) {
  if (
    transformPlotView !== "fit" ||
    !isPolarizationRecipe(getTransformOptionsFromControls()) ||
    isTransformValueTooltipSuppressedAtEvent(event)
  ) {
    return;
  }
  const point = getTransformFitPointFromEvent(event);
  if (!point) return;
  event.preventDefault();
  event.stopPropagation();
  transformFitLastHoverPoint = point;
  transformFitPinnedPoint = {
    viewportPoint: new OpenSeadragon.Point(
      point.viewportPoint.x,
      point.viewportPoint.y,
    ),
  };
  updateTransformFitPinMarker();
  scheduleTransformFitRefresh();
  renderTransformFitInspector();
}

function populateTransformTileSetSelect() {
  if (!transformTileSetSelect) return;

  const previousValue = transformTileSetSelect.value;
  transformTileSetSelect.innerHTML = "";
  tileSets().forEach((tileSet, index) => {
    const option = document.createElement("option");
    option.value = String(index);
    option.textContent = getSnapshotTileSetLabel(tileSet, index);
    transformTileSetSelect.append(option);
  });

  const hasPrevious =
    previousValue !== "" &&
    Array.from(transformTileSetSelect.options).some(
      (option) => option.value === previousValue,
    );
  transformTileSetSelect.value = hasPrevious ? previousValue : "0";
  populateTransformRasterTileSetBSelect();
  populateTransformRasterInputTable();
  populateTransformPolarizationRoleSelects();
}

function inferTileSetModality(tileSet) {
  const explicit = String(tileSet?.modality || "").trim().toLowerCase();
  if (["ppl", "xpl", "cpl"].includes(explicit)) return explicit;
  const label = String(tileSet?.label || "").toLowerCase();
  if (/\bppl\b/.test(label)) return "ppl";
  if (/\bxpl\b/.test(label)) return "xpl";
  if (/\bcpl\b/.test(label)) return "cpl";
  return "";
}

function populatePolarizationRoleSelect(select, modality) {
  if (!select) return;
  const previousValue = select.value;
  select.innerHTML = "";
  const none = document.createElement("option");
  none.value = "-1";
  none.textContent = "None";
  select.append(none);
  tileSets().forEach((tileSet, index) => {
    const option = document.createElement("option");
    option.value = String(index);
    option.textContent = getSnapshotTileSetLabel(tileSet, index);
    select.append(option);
  });
  const hasPrevious = Array.from(select.options).some(
    (option) => option.value === previousValue,
  );
  if (hasPrevious && previousValue !== "-1") {
    select.value = previousValue;
    return;
  }
  const inferredIndex = tileSets().findIndex(
    (tileSet) => inferTileSetModality(tileSet) === modality,
  );
  select.value = String(inferredIndex);
}

function populateTransformPolarizationRoleSelects() {
  populatePolarizationRoleSelect(transformPolarizationPplSelect, "ppl");
  populatePolarizationRoleSelect(transformPolarizationXplSelect, "xpl");
  populatePolarizationRoleSelect(transformPolarizationCplSelect, "cpl");
  populateTransformPolarizationProducts();
}

function getPolarizationRoleIndex(modality, transform = null) {
  const settings = transform || getTransformOptionsFromControls();
  const key = `polarization${modality.toUpperCase()}Index`;
  if (Object.prototype.hasOwnProperty.call(settings, key)) return settings[key];
  const normalizedKey =
    modality === "ppl"
      ? "polarizationPplIndex"
      : modality === "xpl"
        ? "polarizationXplIndex"
        : "polarizationCplIndex";
  return Number(settings[normalizedKey]);
}

function getPolarizationTileSet(modality, transform = null) {
  const index = getPolarizationRoleIndex(modality, transform);
  return index >= 0 ? tileSets()[index] || null : null;
}

function getPolarizationAngles(tileSet) {
  return (tileSet?.tiles || []).map((tile) => Number(tile?.angleDegrees));
}

function getPolarizationFitModel(modality, tileSet) {
  if (!tileSet) return null;
  return PetroPolarizationAnalysis.createHarmonicModel(
    getPolarizationAngles(tileSet),
    modality === "ppl" ? 2 : 4,
  );
}

