function finalizePolyAnnotation(
  constPolylineLabel,
  labelImagePoint,
  imageSize,
  uuid,
  labelViewportPoint,
  labelFontSize,
  labelFontColor,
  labelBackgroundColor,
  labelBackgroundOpacity,
  lineStyle,
  lineWeight,
  lineColor,
  lineOpacity,
  fillColor,
  fillOpacity,
  rectAreaM2,
  rectPerimeterM,
  lineLengthM,
  isPolygonMode,
  XWasPressed,
  isPolylineMode,
  ZWasPressed,
  clickImageCoordinates,
) {
  if (isPolygonMode || XWasPressed) {
    const polygonCoordinates = getCoordinatesWithoutTrailingDuplicate(
      clickImageCoordinates,
    );
    if (
      polygonCoordinates.length > 1 &&
      !coordinatesMatch(
        polygonCoordinates[0],
        polygonCoordinates[polygonCoordinates.length - 1],
      )
    ) {
      polygonCoordinates.push([...polygonCoordinates[0]]);
    }
    addPolygonToGeoJSON(annoJSON, polygonCoordinates, {
      uuid: uuid,
      label: constPolylineLabel,
      xLabel: labelImagePoint.x,
      yLabel: labelImagePoint.y,
      imageTitle: title(),
      pixelsPerMeter: pixelsPerMeter(),
      imageWidth: imageSize.x,
      imageHeight: imageSize.y,
      labelFontSize: labelFontSize,
      labelFontColor: labelFontColor,
      labelBackgroundColor: labelBackgroundColor,
      labelBackgroundOpacity: labelBackgroundOpacity,
      lineStyle: lineStyle,
      lineWeight: lineWeight,
      lineColor: lineColor,
      lineOpacity: lineOpacity,
      fillColor: fillColor,
      fillOpacity: fillOpacity,
      area_m2: rectAreaM2,
      perimeter_m: rectPerimeterM,
    });

    if (!polygonButton.classList.contains("active")) {
      togglePolygonFloaterOn(false);
    }
  }
  if (isPolylineMode || ZWasPressed) {
    const polylineCoordinates = getCoordinatesWithoutTrailingDuplicate(
      clickImageCoordinates,
    );
    addPolylineToGeoJSON(annoJSON, polylineCoordinates, {
      uuid: uuid,
      label: constPolylineLabel,
      xLabel: labelImagePoint.x,
      yLabel: labelImagePoint.y,
      imageTitle: title(),
      pixelsPerMeter: pixelsPerMeter(),
      imageWidth: imageSize.x,
      imageHeight: imageSize.y,
      labelFontSize: labelFontSize,
      labelFontColor: labelFontColor,
      labelBackgroundColor: labelBackgroundColor,
      labelBackgroundOpacity: labelBackgroundOpacity,
      lineStyle: lineStyle,
      lineWeight: lineWeight,
      lineColor: lineColor,
      lineOpacity: lineOpacity,
      length_m: lineLengthM,
      // canvasDraw: true,
    });
  }
  drawShape(polyCanvas, [annoJSON]);

  // Make text and crosshairs
  addText(
    uuid,
    constPolylineLabel,
    labelViewportPoint,
    "anno",
    labelFontColor,
    labelFontSize,
    labelBackgroundColor,
    labelBackgroundOpacity,
  );
}

