function getAnnotationGroupCounts() {
  const counts = new Map();
  annoJSON.features.forEach((feature) => {
    const props = normalizeAnnotationFeature(feature)?.properties;
    if (!props) return;
    counts.set(props.groupId, (counts.get(props.groupId) || 0) + 1);
  });
  return counts;
}

