const Grid = class {
  // All units are in microns.
  constructor({ xMin, yMin, xMax, yMax, step, noPoints }) {
    this.xMin = xMin;
    this.yMin = yMin;
    this.xMax = xMax;
    this.yMax = yMax;
    this.step = step;
    this.noPoints = noPoints;
  }
};

const MIN_GRID_STEP_MICRONS = 2;
const MIN_GRID_POINTS = 2;
const MAX_GRID_POINTS = 5000;
const MAX_GRID_CANDIDATE_POINTS = 250000;
const GRID_STEP_UNIT_MICRONS = Object.freeze({
  um: 1,
  mm: 1000,
  m: 1000000,
});
const GRID_STEP_UNIT_LABELS = Object.freeze({
  um: "µm",
  mm: "mm",
  m: "m",
});

// Initialize grid with default settings.
let grid = new Grid({
  xMin: 20,
  yMin: 10,
  xMax: 80,
  yMax: 90,
  step: 1000,
  noPoints: 600,
});
let gridApplied = false;

